        el("li", {}, el("button", { type: "button", class: `detail-item${item.warn ? " warn" : ""}`, title: t("Show this accessory's card"), onclick: () => open?.(item.details()) },
          el("span", { class: "detail-item-glyph" }, HomeswiftCommon.icon(item.icon)),
