      case "energy-insights": [10, 20, 30].forEach((y, i) => { r(8, y, 48, 7, "th-tile", 2); r(10, y + 1.5, 1.5, 4, ["th-2", "th-7", "th-3"][i], 0.75); r(14, y + 2, [30, 36, 24][i], 3, "th-muted", 1.5); }); break;
