              el("summary", { class: "dash-gallery-title" }, HomeswiftCommon.icon("forward"), el("span", { text: title }),
                el("small", { text: t("{shown} of {total} on the page", { shown: items.filter(([id]) => shown(id)).length, total: items.length }) })),
