        "authorize.html": WebFile(contentType: "text/html; charset=utf-8", body: #"""
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="theme-color" content="#e2bba5" media="(prefers-color-scheme: light)">
<meta name="theme-color" content="#231c19" media="(prefers-color-scheme: dark)">
<meta name="referrer" content="no-referrer">
<title>Connect to Homeswift</title>
<link rel="icon" href="icon.svg" type="image/svg+xml">
<link rel="stylesheet" href="style.css">
<script src="i18n.js"></script>
</head>
<body>
<div class="auth">
  <div class="card authorize">
    <img src="icon.svg" class="logo large" alt="">
    <h1 id="title" data-i18n>Connect to Homeswift</h1>
    <p id="lead" class="muted" data-i18n>Checking the request…</p>
    <p id="leave" class="actions hidden"><a class="button" id="leave-link" rel="noreferrer"></a></p>
    <form id="login" class="hidden">
      <label data-i18n>Username <input name="username" autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" required></label>
      <label data-i18n>Password <input name="password" type="password" autocomplete="current-password" required></label>
      <label id="login-otp" class="hidden" data-i18n>Code from your authenticator app <input name="otp" inputmode="numeric" autocomplete="one-time-code" spellcheck="false" placeholder="123 456" maxlength="9"></label>
      <p class="error" id="login-error" role="alert"></p>
      <button type="submit" class="primary" id="login-submit" data-i18n>Sign in</button>
    </form>
    <form id="consent" class="hidden">
      <fieldset class="scopes" id="scopes"><legend class="muted" data-i18n>It may</legend></fieldset>
      <p class="muted hidden" id="read-only" data-i18n>The MCP server is read-only (readOnly in the HomeswiftAiKit block): whatever you choose, the app can only read.</p>
      <p class="muted" id="destination"></p>
      <p class="error" id="consent-error" role="alert"></p>
      <div class="actions">
        <button type="button" id="deny" data-i18n>Deny</button>
        <button type="submit" class="primary" id="allow" data-i18n data-action-icon="check">Allow</button>
      </div>
      <button type="button" class="link switch-user" id="switch-user" data-i18n>Not you? Sign in as someone else</button>
    </form>
  </div>
</div>
<script src="authorize.js"></script>
</body>
</html>

"""#),
        "authorize.js": WebFile(contentType: "text/javascript; charset=utf-8", body: #"""
"use strict";

// The OAuth sign-in page (/oauth/authorize): an MCP client such as claude.ai sends the user here. They sign in with
// their web UI account (the same login, two-factor code and throttle as the UI's), see which app asks and where
// approving sends them back, choose what it may do, and the bridge redirects to the app with a code or a refusal.
(() => {
  const { t } = HomeswiftI18n;
  const $ = (selector) => document.querySelector(selector);
  document.title = t("Connect to Homeswift");
  const query = Object.fromEntries(new URLSearchParams(location.search));

  async function api(path, { method = "GET", body } = {}) {
    const options = { method, credentials: "same-origin", headers: { "Accept-Language": HomeswiftI18n.locale } };
    if (body !== undefined) { options.headers["Content-Type"] = "application/json"; options.body = JSON.stringify(body); }
    const response = await fetch(path, options);
    const text = await response.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch { json = { error: text }; }
    if (!response.ok) throw Object.assign(new Error(HomeswiftI18n.message((json && json.error) || `HTTP ${response.status}`)), { status: response.status });
    return json;
  }

  /// One of the page's states: the sign-in form, the choice, or a message alone.
  function show(part, lead) {
    $("#login").classList.toggle("hidden", part !== "login");
    $("#consent").classList.toggle("hidden", part !== "consent");
    if (lead !== undefined) $("#lead").textContent = lead;
  }
  const stop = (message) => { $("#title").textContent = t("Cannot connect"); show(null, message); };

  /// A request the bridge cannot answer goes back to the app only when the person clicks: anyone may register an app
  /// and the address it returns to, so going there on its own would send them to any site under the bridge's name.
  function refuse(request) {
    stop(t("The app asked for something Homeswift cannot give ({reason}). Nothing was shared.", { reason: request.reason || request.error }));
    const link = $("#leave-link");
    link.href = request.redirect;
    link.textContent = t("Return to {destination}", { destination: request.destination });
    $("#leave").classList.remove("hidden");
  }

  const scopes = {
    read: [t("Read"), t("See your accessories, rooms, scenes and the bridge's state. Changes nothing.")],
    control: [t("Control"), t("Also turn accessories on and off and run scenes. Locks, garage doors and alarms still ask you first.")],
    admin: [t("Administer"), t("Also change config.json, plugins and settings, and restart the bridge: everything this web UI can do.")],
  };

  async function start() {
    let state;
    try { state = await api("api/auth/state"); } catch (e) { stop(t("The bridge did not answer: {error}", { error: e.message })); return; }
    if (state.setupNeeded) { stop(t("This bridge has no account yet. Open its web UI and create the administrator first.")); return; }
    if (!state.authenticated) {
      show("login", t("Sign in with your Homeswift account to connect an app."));
      $("#login").username.focus();
      return;
    }
    let request;
    try { request = await api(`api/oauth/request?${new URLSearchParams(query)}`); } catch (e) { stop(e.message); return; }
    if (request.redirect) { refuse(request); return; }
    $("#title").textContent = t("Connect {client}", { client: request.client });
    show("consent", state.mode === "form"
      ? t("{client} asks to use your bridge as {username}.", { client: request.client, username: request.username })
      : t("{client} asks to use your bridge. This web UI has no sign-in, so it acts as its administrator.", { client: request.client }));
    const fieldset = $("#scopes");
    fieldset.querySelectorAll(".scope").forEach((node) => node.remove());
    for (const name of request.choices) {
      const input = Object.assign(document.createElement("input"), { type: "radio", name: "scope", value: name, checked: name === request.suggested });
      const label = document.createElement("label");
      label.className = "scope";
      const title = document.createElement("strong");
      title.textContent = scopes[name][0];
      const help = document.createElement("span");
      help.className = "help";
      help.textContent = scopes[name][1];
      label.append(input, title, help);
      fieldset.append(label);
    }
    $("#read-only").classList.toggle("hidden", !request.readOnly);
    const destination = document.createElement("strong");
    destination.textContent = request.destination;
    // The sentence around the address, in the page's language: the address goes where {destination} stands.
    const [before, after = ""] = t("Allowing sends you back to {destination}. You can disconnect it from your account page at any time.").split("{destination}");
    $("#destination").replaceChildren(before, destination, after);
    $("#switch-user").classList.toggle("hidden", state.mode !== "form");
    // Nothing is focused and the answers wait a moment: the Enter that signed in, or a click meant for what was there
    // before, never approves an app the user has not seen.
    const buttons = [$("#allow"), $("#deny")];
    buttons.forEach((button) => { button.disabled = true; });
    setTimeout(() => buttons.forEach((button) => { button.disabled = false; }), 800);
  }

  // Signing in: the web UI's own login, so the session it makes also opens the UI.
  const login = $("#login");
  const askCode = (asked) => {
    $("#login-otp").classList.toggle("hidden", !asked);
    login.otp.required = asked;
    if (asked) login.otp.focus(); else login.otp.value = "";
  };
  for (const name of ["username", "password"]) login[name].addEventListener("input", () => askCode(false));
  login.addEventListener("submit", async (event) => {
    event.preventDefault();
    const submit = $("#login-submit");
    $("#login-error").textContent = "";
    submit.disabled = true;
    submit.textContent = t("Signing in…");
    const body = { username: login.username.value, password: login.password.value };
    if (!$("#login-otp").classList.contains("hidden")) body.otp = login.otp.value;
    try {
      await api("api/auth/login", { method: "POST", body });
      login.password.value = "";
      askCode(false);
      await start();
    } catch (e) {
      if (e.status === 412) askCode(true);
      else {
        $("#login-error").textContent = e.message;
        if (body.otp !== undefined) { login.otp.value = ""; login.otp.focus(); }
      }
    } finally {
      submit.disabled = false;
      submit.textContent = t("Sign in");
    }
  });

  // The answer: the bridge says where to send the browser, with a code or with access_denied.
  async function decide(approve) {
    const buttons = [$("#allow"), $("#deny")];
    buttons.forEach((button) => { button.disabled = true; });
    $("#consent-error").textContent = "";
    const chosen = $("#scopes input:checked");
    if (approve) $("#allow").textContent = t("Connecting…");
    try {
      const answer = await api("api/oauth/decision", { method: "POST", body: { ...query, approve, scope_granted: chosen ? chosen.value : null } });
      location.assign(answer.redirect);
    } catch (e) {
      $("#consent-error").textContent = e.message;
      buttons.forEach((button) => { button.disabled = false; });
      $("#allow").textContent = t("Allow");
    }
  }
  $("#consent").addEventListener("submit", (event) => { event.preventDefault(); decide(true); });
  $("#deny").addEventListener("click", () => decide(false));
  $("#switch-user").addEventListener("click", async () => {
    try { await api("api/auth/logout", { method: "POST" }); } catch {}
    $("#title").textContent = t("Connect to Homeswift");
    await start();
  });

  start();
})();

"""#),
        "automations.js": WebFile(contentType: "text/javascript; charset=utf-8", body: #"""
// The Automations page (/automations, beside Scenes): what the bridge does on its own, a Trigger, Conditions and Steps
// run in order (GLOSSARY.md). Its list with each one's triggers, last run, On and Run; the Assistant's draft from a
// sentence, opened in the editor to review; the editor (/automations/<id>, /automations/new).
(() => {
  "use strict";

  const { t, tn } = HomeswiftI18n;
  const { el, api } = HomeswiftCommon;
  const app = () => window.HomeswiftApp;
  const home = () => window.HomeswiftHome.editor;

  /// What the editor opens with next, instead of an empty Automation: the Assistant's draft, or a Scene to apply.
  let pending = null;
  /// Opens the editor on a new Automation filled with `draft`.
  function draft(value) {
    pending = value;
    app().navigate("/automations/new");
  }

  const stepKinds = [["scene", t("Apply a scene"), "play"], ["set", t("Set a value"), "sliders"], ["wait", t("Wait"), "history"],
    ["waitUntil", t("Wait until"), "sensor"], ["notify", t("Notify"), "bell"], ["tool", t("Plugin action"), "plugin"]];

  async function view(main, [id] = []) {
    if (id) return editor(main, id);
    const [data, accessories] = await Promise.all([api("/api/automations"), api("/api/accessories").catch(() => [])]);
    const names = new Map(accessories.map((one) => [one.id, window.HomeswiftHome.displayName(one)]));
    const admin = app().isAdmin();
    const newButton = admin ? el("a", { class: "button primary", href: "/automations/new", actionIcon: "plus", text: t("New automation") }) : null;
    const cards = data.automations.map((automation) => card(automation, names, admin));
    const empty = el("div", { class: "card empty" }, el("span", { class: "empty-glyph" }, HomeswiftCommon.icon("workflow")),
      el("p", { class: "muted", text: t("No automation yet. One turns the hall light on when there is motion, then off five minutes later; or closes the blinds at sunset on weekdays.") }), newButton);
    app().show(main,
      app().pageHead(t("Automations"), t("What the bridge does on its own: when a trigger fires and the conditions hold, its steps run in order. Locks, garage doors and alarms are never changed by an automation."),
        cards.length ? newButton : null),
      window.HomeswiftHome.scenesTabs("automations"),
      admin && data.assistant ? draftCard() : null,
      cards.length ? el("div", { class: "automation-list" }, cards) : empty);
  }

  /// A sentence for the Assistant, whose draft opens in the editor: nothing is saved before the person does.
  function draftCard() {
    const sentence = el("input", { type: "text", maxLength: 500, required: true, placeholder: t("When the front door opens after sunset, turn the hall light on for five minutes"),
      "aria-label": t("What should happen") });
    const line = home().statusLine();
    const ask = el("button", { type: "submit", actionIcon: "sparkle", text: t("Draft it") });
    return el("form", { class: "card automation-draft", onsubmit: async (event) => {
      event.preventDefault();
      await HomeswiftCommon.busyButton(ask, async () => {
        home().say(line, t("The Assistant is writing it…"));
        const answer = await api("/api/automations/draft", { method: "POST", body: { sentence: sentence.value.trim() } });
        draft({ ...(answer.automation ?? answer.draft), problem: answer.problem });
      }, { report: (e) => home().say(line, e.message, "error") });
    } },
      el("div", { class: "who" }, el("strong", { text: t("Describe it") }), el("p", { class: "muted", text: t("The Assistant drafts the automation; you review it before saving.") })),
      el("div", { class: "automation-draft-row" }, sentence, ask), line);
  }

  /// The scenes' wording of a last run (or a skip), with what the run noted.
  function lastRun(automation) {
    const text = home().lastRun(automation);
    const shown = automation.lastSkipped && (!automation.lastRun || automation.lastSkipped.at > automation.lastRun.at);
    return !shown && automation.lastRun?.reason ? `${text} · ${HomeswiftI18n.message(automation.lastRun.reason)}` : text;
  }

  function card(automation, names, admin) {
    const { describeTrigger, triggerIcons } = home();
    const first = automation.triggers[0];
    const status = el("p", { class: "muted automation-last-run", text: lastRun(automation) });
    const enabled = el("input", { type: "checkbox", role: "switch", checked: automation.enabled, disabled: !admin, "aria-label": t("{name}: on", { name: automation.name }) });
    enabled.addEventListener("change", async () => {
      try { await api(`/api/automations/${encodeURIComponent(automation.id)}`, { method: "PUT", body: { name: automation.name, enabled: enabled.checked } }); }
      catch (e) { enabled.checked = !enabled.checked; HomeswiftCommon.showAlert(e.message); }
    });
    const run = el("button", { type: "button", actionIcon: "play", text: t("Run now"), onclick: async () => {
      await HomeswiftCommon.busyButton(run, async () => {
        const answer = await api(`/api/automations/${encodeURIComponent(automation.id)}/run`, { method: "POST", body: {} });
        if (answer.lastRun) status.textContent = lastRun({ ...automation, lastRun: answer.lastRun, lastSkipped: null });
      }, { report: (e) => HomeswiftCommon.showAlert(e.message) });
    } });
    return el("article", { class: "card automation-card" },
      el("div", { class: "automation-head" },
        el("span", { class: "tile tone-violet", "aria-hidden": "true" }, HomeswiftCommon.icon(triggerIcons[first?.type] ?? "workflow")),
        el("div", { class: "who" }, el("strong", { text: automation.name }),
          el("span", { class: "muted", text: [automation.triggers.map((trigger) => describeTrigger(trigger, names)).join(" · "),
            tn("{n} step", "{n} steps", automation.steps.length), automation.mode === "single" ? t("Single") : null,
            automation.homeKit ? t("In the Home app") : null].filter(Boolean).join(" · ") })),
        el("label", { class: "toggle compact" }, el("span", { class: "switch" }, enabled, el("span")))),
      automation.security ? el("p", { class: "muted note" }, HomeswiftCommon.icon("lock"), el("span", { text: t("It watches or names a lock, a door or an alarm: those are never changed by it.") })) : null,
      status,
      el("div", { class: "actions start" }, run, admin ? el("a", { class: "button", href: `/automations/${encodeURIComponent(automation.id)}`, actionIcon: "edit", text: t("Edit") }) : null));
  }

  // ---- The editor

  async function editor(main, id) {
    const isNew = id === "new";
    const [data, accessories] = await Promise.all([api("/api/automations"), api("/api/accessories")]);
    const scenes = { scenes: data.scenes ?? [] };
    const fromDraft = isNew ? pending : null;
    pending = null;
    const automation = isNew ? { name: "", triggers: [{ type: "time", at: "07:00" }], conditions: [], steps: [], mode: "restart", enabled: true, ...(fromDraft ?? {}) }
      : data.automations.find((one) => one.id === id);
    if (!automation) { app().show(main, el("p", { class: "error", text: t("No such automation.") })); return; }
    const { triggerRow, conditionRow, field, statusLine, say } = home();
    const remove = (row, label, list) => el("button", { type: "button", class: "danger scene-condition-remove", actionIcon: "trash", text: label, onclick: () => { list.delete(row); row.remove(); } });

    const name = el("input", { type: "text", value: automation.name ?? "", maxLength: 64, required: true, placeholder: t("Hall light on motion") });
    const enabled = el("input", { type: "checkbox", checked: automation.enabled !== false });
    const homeKit = el("input", { type: "checkbox", checked: Boolean(automation.homeKit) });
    const mode = el("select", {}, el("option", { value: "restart", text: t("Restart: a new trigger starts it again") }), el("option", { value: "single", text: t("Single: a new trigger is ignored while it runs") }));
    mode.value = automation.mode || "restart";
    const toggle = (input, title, help) => el("label", { class: "toggle" }, el("span", { class: "switch" }, input, el("span")),
      el("span", {}, el("span", { class: "field-title", text: title }), el("p", { class: "help", text: help })));

