      if (distance / pad.clientWidth < DEAD_ZONE) { mark(null); release(); return; }
      const direction = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? "right" : "left") : (dy > 0 ? "down" : "up");
      if (!controls?.directions.includes(direction)) { mark(null); release(); return; }
