    if (!pendingText.size) requestAnimationFrame(() => {
      for (const i of pendingText) {
        const body = nodes[i]?.querySelector(".chat-text");
        if (body) body.replaceChildren(...markdown(items[i].text).childNodes);
      }
      pendingText.clear();
      scrollToEnd();
    });
    pendingText.add(index);
  }

  function itemNode(item) {
    switch (item.kind) {
    case "user":
      return el("div", { class: "chat-user" }, el("p", { text: item.text }));
    case "assistant":
      return el("div", { class: "chat-answer" }, el("div", { class: "chat-text md" }, ...markdown(item.text).childNodes));
    case "tool":
      return el("div", { class: `chat-step ${item.state}`, title: item.name },
        el("span", { class: "chat-step-mark", "aria-hidden": "true" }),
        el("span", {}, el("span", { class: "chat-step-title", text: item.title }), item.summary ? el("span", { class: "chat-step-summary", text: ` · ${item.summary}` }) : null),
        el("span", { class: "visually-hidden", text: ` ${{ running: t("(running)"), failed: t("(failed)"), declined: t("(not allowed)") }[item.state] ?? t("(done)")}` }));
    case "confirm":
      return confirmCard(item);
    case "setup":
      // A Setup the Assistant started, at a step the person finishes in the sheet: a password, a sign-in page, a button.
      return el("div", { class: "chat-setup" },
        el("p", { text: item.message ? t(item.message, item.values ?? {}) : t("This step continues in the Setup sheet.") }),
        el("button", { type: "button", class: "primary", actionIcon: "forward", text: t("Continue in the Setup sheet"),
          onclick: () => window.HomeswiftSetup?.resume(item) }));
    default:
      return el("p", { class: "chat-error", role: "alert", text: HomeswiftI18n.message(item.text) });
    }
  }

  /// The conversation as Markdown, to paste in a report when something went wrong: the messages, the steps and
  /// the changes asked for, without the tools' arguments or answers.
  function transcript() {
    const status = { running: t("(running)"), failed: t("(failed)"), declined: t("(not allowed)") };
    const lines = [`# ${t("Assistant")}${info.model ? ` · ${info.model}` : ""} · ${HomeswiftI18n.formatDate(new Date(), { year: "numeric", month: "numeric", day: "numeric", hour: "numeric", minute: "2-digit", second: "2-digit" })}`, ""];
    for (const item of items) {
      switch (item.kind) {
      case "user": lines.push(`**${t("You")}:** ${item.text}`, ""); break;
      case "assistant": lines.push(`**${t("Assistant")}:** ${item.text}`, ""); break;
      case "tool": lines.push(`- ${item.title}${item.summary ? ` · ${item.summary}` : ""} \`${item.name}\` ${status[item.state] ?? t("(done)")}`); break;
      case "setup": lines.push(`- ${t("Continue in the Setup sheet")}: ${item.message ? t(item.message, item.values ?? {}) : ""}`.trimEnd()); break;
      case "confirm": lines.push(`- ${describe(item)} ${item.state === "pending" ? "" : item.state === "allowed" ? t("Allowed") : t("Not allowed")}`.trimEnd()); break;
      default: lines.push(`> ${HomeswiftI18n.message(item.text)}`, "");
      }
    }
    return lines.join("\n").replace(/\n{3,}/g, "\n\n").trim() + "\n";
  }

  let copiedTimer = null;

  /// The copy button as it is, or showing that it worked (a check, for two seconds).
  function showCopied(copied) {
    panel.copy.replaceChildren(icon(copied ? "check" : "copy"));
    panel.copy.setAttribute("aria-label", copied ? t("Copied") : t("Copy the conversation"));
  }

  async function copyConversation() {
    clearTimeout(copiedTimer);
    let note;
    if (!items.length) {
      note = t("Nothing to copy yet.");
    } else {
      try {
        await copyText(transcript());
        showCopied(true);
        note = t("Conversation copied: paste it where you report the problem.");
      } catch (e) {
        note = e.message;
      }
    }
    voiceNote = note;
    renderControls();
    // Only this note goes: one the mic wrote since stays.
    copiedTimer = setTimeout(() => {
      showCopied(false);
      if (voiceNote === note) { voiceNote = ""; renderControls(); }
    }, 2000);
  }

  /// A change the Assistant wants to make: what it is in words, the details on demand, and the choice.
  function confirmCard(item) {
    const pending = item.state === "pending";
    const answer = (allow) => async (event) => {
      event.currentTarget.closest(".chat-confirm").querySelectorAll("button").forEach((button) => { button.disabled = true; });
      try { await api("/api/assistant/chat/confirm", { method: "POST", body: { id: item.id, allow } }); } catch (e) { showError(e.message); }
    };
    const changes = changeList(item.preview);
    const details = el("details", {},
      el("summary", { text: changes ? t("The whole request") : item.preview !== undefined ? t("What would change") : t("Details") }),
      jsonView(changes ? item.arguments : item.preview ?? item.arguments));
    return el("div", { class: `chat-confirm ${item.state}` },
      el("div", { class: "chat-confirm-head" }, el("strong", { text: describe(item) }),
        pending ? null : el("span", { class: `pill status ${item.state === "allowed" ? "on" : "standby"}`, text: item.state === "allowed" ? t("Allowed") : t("Not allowed") })),
      el("p", { text: pending ? t("{title}. Nothing changes until you allow it.", { title: item.title }) : item.title }),
      changes,
      details,
      pending ? el("div", { class: "chat-confirm-actions" },
        el("button", { actionIcon: "close", type: "button", text: t("Don't allow"), onclick: answer(false) }),
        el("button", { actionIcon: "check", type: "button", class: "primary", text: t("Allow"), onclick: answer(true) })) : null);
  }

  /// What a config dry run would change, a line per setting with its new value; null for other previews.
  function changeList(preview) {
    if (!preview || !Array.isArray(preview.changes) || !preview.config) return null;
    const valueAt = (path) => path.match(/[^.[\]]+/g).reduce((value, key) => value?.[/^\d+$/.test(key) ? Number(key) : key], preview.config);
    const shown = (value) => value === undefined ? t("removed") : value === "__REDACTED__" ? t("(secret, kept)") : JSON.stringify(value);
    const lines = preview.changes.slice(0, 8).map((path) => el("li", {},
      el("code", { text: path.replace(/^platforms\[\d+\]\./, "") }), " ", el("span", { text: `→ ${shown(valueAt(path))}`.slice(0, 120) })));
    if (preview.changes.length > 8) lines.push(el("li", { class: "muted", text: tn("and {n} more", "and {n} more", preview.changes.length - 8) }));
    return lines.length ? el("ul", { class: "chat-changes" }, lines) : el("p", { class: "muted", text: t("Nothing would change.") });
  }

  /// A change in a sentence, from the tool and its arguments.
  function describe({ tool, arguments: args = {} }) {
    const settings = Object.keys(args.settings || {});
    switch (tool) {
    case "update_settings":
      if (args.accessories) return tn("Change the settings of one accessory?", "Change the settings of {n} accessories?", Object.keys(args.accessories).length);
      if (args.accessory) {
        return settings.length
          ? t("Change {settings} of {block}?", { settings: settings.join(", "), block: args.accessory })
          : t("Change the settings of {block}?", { block: args.accessory });
      }
      return settings.length
        ? t("Change {settings} of {block}?", { settings: settings.join(", "), block: args.plugin?.name || args.plugin?.platform })
        : t("Change the settings of {block}?", { block: args.plugin?.name || args.plugin?.platform });
    case "patch_config":
      return settings.length
        ? t("Change {settings} of {block}?", { settings: settings.join(", "), block: args.name || args.platform })
        : t("Change the settings of {block}?", { block: args.name || args.platform });
    case "update_config": return t("Replace the whole config.json? A backup is kept.");
    case "restore_config": return t("Restore config.json from {backup}?", { backup: args.backup });
    case "restart_bridge": return t("Restart homeswift? Connections drop for a few seconds.");
    case "set_security_accessory": return t("Set {characteristic} to {value} on {id}?", { characteristic: args.characteristic, value: JSON.stringify(args.value), id: args.id });
    default: return t("Allow {tool}?", { tool });
    }
  }

  function showError(text) {
    if (!panel) return;
    panel.log.append(el("p", { class: "chat-error", role: "alert", text }));
    scrollToEnd();
  }

  /// Keeps the newest line in view, unless the person scrolled up to read.
  function scrollToEnd(force = false) {
    const { log } = panel;
    if (force || log.scrollHeight - log.scrollTop - log.clientHeight < 120) log.scrollTop = log.scrollHeight;
  }

  /// The send button turns into stop while the Assistant works; the glow turns around the panel meanwhile.
  function renderControls() {
    if (!panel) return;
    const { sheet, send, note, log } = panel;
    sheet.classList.toggle("working", running);
    log.setAttribute("aria-busy", String(running));
    send.classList.toggle("stop", running);
    send.setAttribute("aria-label", running ? t("Stop") : t("Send"));
    send.title = running ? t("Stop") : t("Send (Enter)");
    const waiting = running && !items.some((item) => item.kind === "confirm" && item.state === "pending") && items[items.length - 1]?.kind !== "assistant";
    let thinking = log.querySelector(".chat-thinking");
    if (waiting && !thinking) log.append(thinking = el("p", { class: "chat-thinking", text: t("Thinking…") }));
    if (waiting) log.append(thinking);   // stays last
    if (!waiting) thinking?.remove();
    const provider = providerNames[info.provider] || info.provider || t("Assistant");
    const cost = usage && usage.cost != null && usage.cost > 0
      ? new Intl.NumberFormat(HomeswiftI18n.numberLocale, { style: "currency", currency: "USD", minimumFractionDigits: usage.cost < 0.01 ? 4 : 2, maximumFractionDigits: usage.cost < 0.01 ? 4 : 2 }).format(usage.cost) : null;
    note.textContent = listening ? t("Listening… tap the mic again when you are done.") : voiceNote
      || (cost ? t("{provider} · {cost} so far. Changes always ask first.", { provider, cost }) : t("{provider}. Changes always ask first.", { provider }));
  }

  // ---- The model --------------------------------------------------------------------------------------------

  /// The provider's models (`/api/assistant/models`: `{ models: [{ id, name }], default, error? }`), asked once a page.
  let models = null;
  async function loadModels() {
    if (models) return models;
    try { models = await api("/api/assistant/models"); } catch (e) { return { models: [], error: e.message }; }
    showModel();
    return models;
  }

  /// The model under the title, by the provider's name for it when the list has one.
  function showModel() {
    if (!panel) return;
    const known = models?.models?.find((one) => one.id === info.model);
    panel.modelLabel.textContent = known?.name || info.model || "";
    panel.modelButton.setAttribute("aria-label", t("Model: {model}. Choose another", { model: known?.name || info.model || "" }));
  }

  /// The menu of models, the one answering ticked and the block's marked Default. A choice holds from the next message on.
  async function chooseModel(trigger, keyboard) {
    const listed = await loadModels();
    const list = [...(listed.models || [])];
    // A model the list does not name (a custom one in the block) stays choosable.
    for (const id of [info.model, info.defaultModel]) if (id && !list.some((one) => one.id === id)) list.unshift({ id });
    menu(trigger, [
      { heading: t("Model"), detail: listed.error ? t("The provider's list could not be read: {error}", { error: listed.error }) : providerNames[info.provider] || info.provider },
      ...list.map((one) => ({ label: one.name || one.id, count: one.id === info.defaultModel ? t("Default") : undefined, checked: one.id === info.model,
        onSelect: () => pickModel(one.id) })),
    ], { keyboard });
  }

  async function pickModel(id) {
    if (id === info.model) return;
    try {
      await api("/api/preferences", { method: "PUT", body: { assistantModel: id === info.defaultModel ? null : id } });
    } catch (e) { showError(e.message); return; }
    info.model = id;
    showModel();
  }

  // ---- Voice ------------------------------------------------------------------------------------------------

  let recognition = null;
  let listening = false;
  let voiceNote = "";

  function setUpMic() {
    const { mic } = panel;
    if (!window.isSecureContext) {
      mic.classList.add("unavailable");
      mic.title = t("Voice needs HTTPS: turn on https in the HomeswiftUI settings, or open this page on localhost.");
    }
    let pressedAt = 0;
    // A mouse starts on the press, so holding it down is push to talk. A finger starts on the tap (its click): Safari
    // lets a page listen only from a tap that ended, and a touch's press is not one, so it refused to start.
    mic.addEventListener("pointerdown", (event) => {
      if (event.pointerType !== "mouse" || event.button !== 0) return;
      pressedAt = event.timeStamp;
      if (!listening) startListening();
      else stopListening(false);
    });
    // Held down and let go: push to talk. A tap keeps listening until the next tap or a pause.
    mic.addEventListener("pointerup", (event) => {
      if (event.pointerType === "mouse" && listening && event.timeStamp - pressedAt > 400) stopListening(false);
    });
    mic.addEventListener("click", (event) => {
      // A mouse was handled on its press; a keyboard's Enter or Space below.
      if (event.pointerType === "mouse" || event.detail === 0) return;
      listening ? stopListening(false) : startListening();
    });
    mic.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") { event.preventDefault(); listening ? stopListening(false) : startListening(); }
    });
  }

  function startListening() {
    if (!window.isSecureContext) {
      voiceNote = t("Voice needs HTTPS here: turn on https in Plugins › HomeswiftUI › Settings (or open the page on localhost).");
      renderControls();
      return;
    }
    // A press while an answer runs still listens: the words wait in the field until the answer is done.
    if (recognition) return;   // the last one is still finishing
    voiceNote = "";
    window.speechSynthesis?.cancel();
    const current = new Recognition();
    recognition = current;
    current.lang = voiceLanguage();
    current.interimResults = true;
    current.continuous = false;
    const before = panel.input.value ? `${panel.input.value} ` : "";
    // What was heard: Safari on iOS often ends without marking a result final, so the last words count either way.
    let heardText = "";
    let failed = false;
    current.onresult = (event) => {
      heardText = [...event.results].map((result) => result[0].transcript).join("");
      panel.input.value = before + heardText;
      grow();
    };
    current.onerror = (event) => {
      // Our own stop or cancel: nothing to say.
      if (event.error === "aborted") return;
      failed = true;
      voiceNote = event.error === "not-allowed" ? t("The browser did not allow the microphone for this page: allow it in the site's settings, then tap the mic again.")
        // Safari says so when Siri & Dictation is off, or when dictation is not offered where the page runs.
        : event.error === "service-not-allowed" ? t("Dictation is not available here. On an iPhone or iPad, turn on Enable Dictation in Settings › General › Keyboard; if this page was added to the Home Screen, try it in Safari.")
        : event.error === "audio-capture" ? t("No microphone was found.")
        : event.error === "network" ? t("Dictation could not reach its speech service. Check the connection and try again.")
        : event.error === "language-not-supported" ? t("Dictation does not support {language}: choose another Voice language from the Settings menu.", { language: current.lang })
        : event.error === "no-speech" ? t("Nothing was heard. Tap the mic and speak.") : t("Voice stopped: {error}.", { error: event.error });
    };
    current.onend = () => {
      if (recognition !== current) return;
      const send = current.sendWhenDone !== false;
      listening = false;
      recognition = null;
      panel.sheet.classList.remove("listening");
      const heard = send && !failed && heardText.trim();
      if (heard && running) voiceNote = t("Your words are in the field: send them once the answer is done.");
      renderControls();
      const text = panel.input.value.trim();
      if (heard && text && !running) submit(text, true);
    };
    try {
      current.start();
    } catch (e) {
      recognition = null;
      voiceNote = t("Voice did not start: {error}", { error: e.message });
      renderControls();
      return;
    }
    listening = true;
    panel.sheet.classList.add("listening");
    renderControls();
  }

  /// `cancel` keeps the words in the field without sending them.
  function stopListening(cancel) {
    if (!recognition) return;
    recognition.sendWhenDone = !cancel;
    recognition.stop();
  }

  /// An answer to a spoken message, read out: plain text, without Markdown's marks.
  function speak(text) {
    if (!text || !window.speechSynthesis) return;
    // Tables: the delimiter rows go, cells are read as a list.
    const plain = text.replace(/```[\s\S]*?```/g, "").replace(/^\s*\|?[\s:|-]*-[\s:|-]*\|?\s*$/gm, "").replace(/\s*\|\s*/g, ", ")
      .replace(/[*_`#>~]/g, "").replace(/\[([^\]]+)\]\([^)]+\)/g, "$1");
    const utterance = new SpeechSynthesisUtterance(plain);
    utterance.lang = voiceLanguage();
    speechSynthesis.speak(utterance);
  }

  // ---- The button in the header -----------------------------------------------------------------------------

  async function mount() {
    try {
      info = await api("/api/assistant");
    } catch { return; }
    if (!info.enabled) return;
    const header = $("header");
    if (!header || header.querySelector(".chat-open")) return;
    const shortcut = /Mac|iPhone|iPad/.test(navigator.platform) ? "⌘K" : "Ctrl+K";
    trigger = el("button", {
      type: "button", class: "chat-open", "aria-expanded": "false", "aria-haspopup": "dialog", "aria-label": t("Assistant"), title: t("Ask the Assistant ({shortcut})", { shortcut }),
      "aria-keyshortcuts": "Meta+K Control+K", onclick: () => toggle(),
    }, sparkle());
    header.insertBefore(trigger, header.querySelector("#user"));
    // A phone: the button floats above the sections' button at the bottom right, in the thumb's reach, rather than in
    // the header at the top. The header's glass makes it the box fixed things inside it are placed in, so the button
    // moves to a dock of its own, and back into the header on a wider window.
    const dock = el("div", { class: "chat-dock" });
    const place = () => {
      if (phone.matches) {
        if (!dock.isConnected) document.body.append(dock);
        if (trigger.parentNode !== dock) dock.append(trigger);
      } else if (trigger.parentNode !== header) {
        header.insertBefore(trigger, header.querySelector("#user"));
        dock.remove();
      }
    };
    place();
    phone.addEventListener("change", place);
    // Cmd+K (Ctrl+K elsewhere) opens the chat from anywhere, and closes it, as Glass UI's palette.
    document.addEventListener("keydown", (event) => {
      // Not from the sign-in screen: the button is in the hidden app then (on a phone, in its dock while the app is hidden).
      if (!trigger?.isConnected || trigger.closest(".hidden") || document.querySelector("#app.hidden")) return;
      if ((event.metaKey || event.ctrlKey) && !event.altKey && !event.shiftKey && event.key.toLowerCase() === "k" && !event.isComposing) {
        event.preventDefault();
        toggle();
      }
    });
    phone.addEventListener("change", () => { if (isOpen()) { panel.scrim.hidden = !phone.matches; draw(openness.value); } });
  }

  /// Opens the chat with `text` typed in, for the person to finish and send.
  function ask(text) {
    toggle(true);
    panel.input.value = text;
    grow();
    setTimeout(() => { panel.input.focus(); panel.input.setSelectionRange(text.length, text.length); }, 60);
  }

  /// Signed out (app.js): the panel closes at once and forgets the conversation it shows, so whoever signs in next
  /// on this browser starts from their own.
  function signedOut() {
    session++;
    if (!panel) return;
    if (listening) stopListening(true);
    window.speechSynthesis?.cancel();
    cancelAnimationFrame(openness.frame);
    openness.value = 0;
    openness.velocity = 0;
    openness.target = 0;
    panel.sheet.hidden = true;
    panel.scrim.hidden = true;
    trigger?.setAttribute("aria-expanded", "false");
    closeHistory(false);
    items = [];
    nodes = [];
    running = false;
    usage = null;
    spoken = false;
    loaded = false;
    panel.input.value = "";
    panel.log.replaceChildren();
    renderControls();
  }

  /// The language chosen for voice, else the page's.
  const voiceLanguage = () => voiceChoice || HomeswiftI18n.locale || "en-US";

  window.HomeswiftChat = { mount, ask, signedOut, open: () => toggle(true), available: () => Boolean(info?.enabled) };
  // The UI's own page mounts it once signed in; a plugin page is signed in already.
  if (document.querySelector('meta[name="homeswift-plugin"]')) mount();
})();

"""#),
        "common.js": WebFile(contentType: "text/javascript; charset=utf-8", body: #"""
// What every page of the web UI shares, the UI's own and plugins' alike: $ and el, which build and find elements;
// the tiles, an icon on a colour, as the Home app draws them; and the Assistant's Markdown and sparkle. Loaded
// before the page's own script.
(() => {
  "use strict";

  // i18n.js is the first script of every page.
  const { t } = HomeswiftI18n;

  const $ = (selector, root = document) => root.querySelector(selector);
  const el = (tag, attrs = {}, ...children) => {
    const node = document.createElement(tag);
    for (const [key, value] of Object.entries(attrs)) {
      if (key === "actionIcon") continue;
      if (key === "class") node.className = value;
      else if (key === "text") node.textContent = value;
      else if (key.startsWith("on")) node.addEventListener(key.slice(2), value);
      // Attributes with no property of the same name: data-*, aria-* (a screen reader reads those).
      else if (value === undefined || value === null || value === false) continue;
      else if (key.startsWith("data-") || key.startsWith("aria-")) node.setAttribute(key, value);
      else node[key] = value;
    }
    // A CSS mask keeps the decorative icon when async actions replace their text.
    if (attrs.actionIcon) decorateAction(node, attrs.actionIcon);
    for (const child of children.flat()) if (child != null) node.append(child.nodeType ? child : document.createTextNode(String(child)));
    // A search field as iOS's: no capitals or corrections, a Search key, and on a touch screen that key puts the
    // keyboard away (the results are already there).
    if (tag === "input" && node.type === "search") {
      node.setAttribute("enterkeyhint", "search");
      node.setAttribute("autocapitalize", "none");
      node.setAttribute("autocorrect", "off");
      node.spellcheck = false;
      node.addEventListener("keydown", (event) => { if (event.key === "Enter" && !event.isComposing && matchMedia("(pointer: coarse)").matches) node.blur(); });
    }
    return node;
  };

  // Line icons: 24-unit boxes, round caps, the current colour.
  const icons = {
    wingman: '<g transform="translate(0 4.32) scale(.048)"><g fill="currentColor" stroke="none"><path d="M8 12C65 48 155 88 180 110C198 121 204 136 195 148L165 177C180 144 170 131 149 121C47 95 6 88 8 12Z M36 112L150 152L132 177C64 163 42 161 36 112Z M58 177L121 193L109 221C77 220 63 203 58 177Z"/><g transform="translate(500 0) scale(-1 1)"><path d="M8 12C65 48 155 88 180 110C198 121 204 136 195 148L165 177C180 144 170 131 149 121C47 95 6 88 8 12Z M36 112L150 152L132 177C64 163 42 161 36 112Z M58 177L121 193L109 221C77 220 63 203 58 177Z"/></g></g><path d="M136 220L250 104L364 220M153 205V305H347V205" fill="none" stroke="currentColor" stroke-width="29" stroke-linecap="round" stroke-linejoin="round"/></g>',
    power: '<path d="M12 3v9M6.3 5.8a8 8 0 1 0 11.4 0"/>',
    // Full screen: a frame with its corners pulled out, top right and bottom left.
    expand: '<rect x="3.5" y="3.5" width="17" height="17" rx="2.5"/><path d="M13.5 7.5h3v3M10.5 16.5h-3v-3"/>',
    // Leaving full screen: expand's corners turned inward.
    collapse: '<rect x="3.5" y="3.5" width="17" height="17" rx="2.5"/><path d="M16.5 10.5h-3v-3M7.5 13.5h3v3"/>',
    // The web UI: a browser window with a page of tiles in it.
    browser: '<rect x="3" y="4" width="18" height="16" rx="2.5"/><path d="M3 8.5h18M6 6.25h0M8.5 6.25h0"/><rect x="6.5" y="11.5" width="4.5" height="5" rx="1"/><path d="M14 12.5h3.5M14 15.5h3.5"/>',
