          HomeswiftCommon.icon(sourceIcons[entry.source.kind] ?? "accessory"), el("span", { text: sourceText(entry.source) })));
    }
    reload();
  }

  window.HomeswiftHistory = { panel, logbookView, sourceText };
})();

"""#),
        "home.js": WebFile(contentType: "text/javascript; charset=utf-8", body: #"""
// Rooms and hidden accessories, the Quick Controls, scenes and their automations, and notifications: the views
// ported from Glass UI. app.js hands its helpers over with install() before the first view is drawn.
(() => {
  "use strict";

  const { $, el, tile, sparkle, menuButton, fact } = HomeswiftCommon;
  const { t, tn } = HomeswiftI18n;
  let app = null;

  // Stable Sunday-based ids for storage, localized labels and display order for people.
  const weekdayFormat = HomeswiftI18n.dateTimeFormat({ weekday: "short", timeZone: "UTC" });
  const weekdayFullFormat = HomeswiftI18n.dateTimeFormat({ weekday: "long", timeZone: "UTC" });
  const weekdays = Array.from({ length: 7 }, (_, day) => weekdayFormat.format(new Date(Date.UTC(2024, 0, 7 + day))));
  const weekdayNames = Array.from({ length: 7 }, (_, day) => weekdayFullFormat.format(new Date(Date.UTC(2024, 0, 7 + day))));
  const firstWeekday = HomeswiftI18n.firstWeekday;
  const weekdayOrder = Array.from({ length: 7 }, (_, offset) => (firstWeekday + offset) % 7);
  const operators = [["eq", t("is")], ["neq", t("is not")], ["gt", t("is above")], ["gte", t("is at least")], ["lt", t("is below")], ["lte", t("is at most")]];
  const displayName = (accessory) => accessory.displayName || accessory.name;
  const { statusLine, say, field } = HomeswiftCommon;

  // ---- Rooms, hidden accessories, display names ------------------------------------------------------

  async function changeLayout(body) {
    return app.api("/api/rooms", { method: "PUT", body });
  }

  /// Changes Accessory Settings (room, Hidden, Name), by accessory id, in one write.
  async function changeSettings(byID) {
    return app.api("/api/settings/accessories", { method: "PATCH", body: byID });
  }

  /// A room for the settings: none is "" for a mirrored accessory (not the room its controller suggests), else cleared.
  const roomSetting = (accessory, room) => room || (accessory?.mirroredFrom ? "" : null);

  /// What an accessory card's menu adds: Move to room (its room, an Accessory Setting, as the Settings sheet's Room
  /// sets it) and the Quick Controls (the Arrangement). Its Name, Hidden and Not in Home are in its Settings sheet
  /// (settings.js, the menu's Settings…).
  function layoutActions(accessory) {
    const done = (promise) => promise.then(() => app.route()).catch((e) => HomeswiftCommon.showAlert(e.message));
    return [
      accessory.platform ? { label: t("Move to room…"), icon: "room", onSelect: async () => {
        // The menu has given the focus back to its ⋯ button: the rooms open under it.
        const trigger = document.activeElement;
        let rooms = [];
        try { rooms = (await app.api("/api/rooms")).rooms.map((room) => room.name); } catch {}
        HomeswiftSettings.roomMenu(trigger, { current: accessory.room ?? "", rooms, onChoose: (name) => {
          if (name === (accessory.room ?? "")) return;
          return done(changeSettings({ [accessory.id]: { room: roomSetting(accessory, name) } }));
        } });
      } } : null,
      { label: accessory.favourite ? t("Remove from Quick Controls") : t("Add to Quick Controls"), icon: "star", onSelect: () => done(changeLayout({ accessories: { [accessory.id]: { favourite: !accessory.favourite } } })) },
    ].filter(Boolean);
  }

  async function chooseRoom(accessory, change, note = "") {
    let rooms = [];
    try { rooms = (await app.api("/api/rooms")).rooms.map((room) => room.name); } catch {}
    const room = await HomeswiftCommon.promptDialog((rooms.length
      ? t("The room of {name}. Rooms: {rooms}. A new name adds the room; empty takes it out of its room.", { name: displayName(accessory), rooms: rooms.join(", ") })
      : t("The room of {name}. A new name adds the room; empty takes it out of its room.", { name: displayName(accessory) })) + (note ? `\n\n${note}` : ""), accessory.room || "");
    if (room !== null) await change({ room: room.trim() || null });
  }

  async function moveGroupToRoom(group, accessories) {
    const members = group.members.map((id) => accessories.find((a) => a.id === id));
    const room = members.every((a) => a && a.room === members[0]?.room) ? members[0]?.room : "";
    await chooseRoom({ name: group.name, room }, async (fields) => {
      // One settings write for every member; no device writes.
      // Only a plugin's accessory has Accessory Settings: one of another kind would refuse the whole write.
      const movable = members.filter((accessory) => accessory?.platform);
      await changeSettings(Object.fromEntries(movable.map((accessory) => [accessory.id, { room: roomSetting(accessory, fields.room) }])));
      await app.route();
    }, t("Moves every member of this group, in the Home app too once this bridge is linked to Apple Home."));
  }

  /// The room an accessory is shown in: its own when the Arrangement knows it, else none ("").
  const roomOf = (accessory, rooms) => (accessory.room && rooms.includes(accessory.room) ? accessory.room : "");
  /// The Accessories page's accessories by room, in the layout's order; those in no room last.
  function groupByRoom(accessories, rooms) {
    const byName = (a, b) => displayName(a).localeCompare(displayName(b));
    const groups = rooms.map((room) => [room, accessories.filter((a) => a.room === room).sort(byName)]).filter(([, list]) => list.length);
    const rest = accessories.filter((a) => !roomOf(a, rooms)).sort(byName);
    return rest.length ? [...groups, [groups.length ? t("No room") : t("Accessories"), rest]] : groups;
  }

  /// The Assistant's rooms and names, to review: each suggestion can be kept or left; Apply saves what is kept, as the
  /// accessories' settings: a name is its Name, in the Home app too.
  async function suggestRooms(host, accessories) {
    host.querySelector(".suggest")?.remove();
    const panel = el("div", { class: "card panel suggest" },
      el("div", { class: "panel-head" }, el("div", {}, el("h2", {}, sparkle(), " ", t("Suggested rooms")), el("p", { class: "muted", text: t("The Assistant is sorting your accessories into rooms…") }))));
    host.prepend(panel);
    panel.classList.add("ai-busy");
    let result;
    try {
      result = await app.api("/api/rooms/suggest", { method: "POST", body: {} });
    } catch (e) {
      panel.replaceChildren(el("p", { class: "error", text: e.message }), el("div", { class: "actions" }, el("button", { actionIcon: "close", text: t("Close"), onclick: () => panel.remove() })));
      return;
    } finally { panel.classList.remove("ai-busy"); }
    const byID = new Map(accessories.map((a) => [a.id, a]));
    const checks = [];
    const check = (data, label, detail) => {
      const input = el("input", { type: "checkbox", checked: true });
      checks.push({ input, data });
      return el("label", { class: "toggle compact" }, input, el("span", {}, el("span", { text: label }), detail ? el("span", { class: "help", text: detail }) : null));
    };
    const rooms = result.rooms.filter((room) => room.accessories.length).map((room) => el("div", { class: "suggest-room" },
      el("div", { class: "service-name", text: room.name }),
      room.accessories.map((id) => {
        const accessory = byID.get(id);
        const moved = accessory?.room && accessory.room !== room.name ? t("now in {room}", { room: accessory.room }) : accessory?.room === room.name ? t("already there") : null;
        return check({ id, room: room.name }, accessory ? displayName(accessory) : id, moved);
      })));
    const renames = result.renames.map((rename) => check({ id: rename.id, name: rename.name }, `${rename.current} → ${rename.name}`, rename.reason));
    const orphans = result.orphans.map((orphan) => el("li", {}, el("strong", { text: orphan.name }), ` ${orphan.reason}`));
    const line = statusLine();
    const apply = el("button", { actionIcon: "check", class: "primary", text: t("Apply what is ticked"), onclick: async () => {
      const changes = {};
      for (const { input, data } of checks) {
        // Only a plugin's accessory has Accessory Settings (the bridge suggests no name for a mirrored one).
        if (!input.checked || !byID.get(data.id)?.platform) continue;
        changes[data.id] = { ...changes[data.id], ...(data.room ? { room: data.room } : { name: data.name }) };
      }
      apply.disabled = true;
      try { await changeSettings(changes); app.route(); } catch (e) { say(line, e.message, "error"); apply.disabled = false; }
    } });
    panel.replaceChildren(
      el("div", { class: "panel-head" },
        el("div", {}, el("h2", {}, sparkle(), " ", t("Suggested rooms")),
          el("p", { class: "muted", text: t("From {model}. Untick what you do not want; nothing changes until you apply. Names are given in the Home app too.", { model: result.model }) })),
        el("button", { actionIcon: "close", class: "link", text: t("Dismiss"), onclick: () => panel.remove() })),
      rooms.length ? el("div", { class: "suggest-rooms" }, rooms) : el("p", { class: "muted", text: t("No room to suggest.") }),
      renames.length ? el("div", {}, el("div", { class: "service-name", text: t("Clearer names") }), renames) : null,
      orphans.length ? el("div", {}, el("div", { class: "service-name", text: t("Worth a look") }), el("ul", { class: "help" }, orphans)) : null,
      el("div", { class: "actions" }, apply), line);
  }

  // ---- Quick Controls --------------------------------------------------------------------------------

  /// The favourite accessories by room, and the scenes to run: a section of the Status page, and the whole of
  /// /quick (a page for a phone's home screen). Draws once its data is there.
  function quickSection(accessories, { standalone = false } = {}) {
    const section = el("section", { class: "quick" });
    (async () => {
      const [list, scenes] = await Promise.all([
        accessories ? Promise.resolve(accessories) : app.api("/api/accessories").then((all) => app.withSlugs(all, "accessory")),
        app.api("/api/scenes").then((answer) => answer.scenes).catch(() => []),
      ]);
      const favourites = list.filter((a) => a.favourite && !a.hidden);
      if (!favourites.length && !scenes.length) {
        if (standalone) section.append(el("div", { class: "card empty" }, el("span", { class: "empty-glyph" }, HomeswiftCommon.icon("star")), el("p", { class: "muted", text: t("Nothing here yet. On the Accessories page, a card's menu adds it to the Quick Controls; scenes you make show here too.") })));
        return;
      }
      section.classList.add("card");
      const rooms = [...new Set(favourites.map((a) => a.room).filter(Boolean))];
      // `append` is the DOM's: it writes null and arrays as text, so the parts go in flat and without the empty ones.
      section.append(...[
        standalone ? null : el("div", { class: "section-head" }, el("h2", { text: t("Quick controls") }), el("a", { href: "/quick", class: "button small", actionIcon: "open", text: t("Open on its own") })),
        scenes.length ? el("div", { class: "quick-scenes" }, scenes.map((scene) => sceneButton(scene))) : null,
        groupByRoom(favourites, rooms).map(([room, members]) => [
          rooms.length ? el("div", { class: "service-name", text: room }) : null,
          // The accessories' widgets, as the Accessories page draws them.
          el("div", { class: "wall" }, members.map((accessory) => app.accessoryCard(accessory))),
        ]),
      ].flat(2).filter(Boolean));
    })().catch((e) => section.append(el("p", { class: "error", text: e.message })));
    return section;
  }

  // Artwork ids come from the server catalogue; never accept an arbitrary image URL.
  function artworkImage(id, className = "scene-artwork") {
    return typeof id === "string" && /^[a-z0-9-]+$/.test(id)
      ? el("img", { class: className, src: `/artwork-${id}.webp`, alt: "", loading: "lazy", decoding: "async" }) : null;
  }

  /// A scene's picture: the one a person gave it (by version, so the browser keeps it until it changes), else its
  /// catalogue artwork.
  function sceneImage(scene, className = "scene-artwork") {
    if (typeof scene.picture === "string" && /^[a-z0-9]+$/.test(scene.picture)) {
      return el("img", { class: className, src: `/api/scenes/${encodeURIComponent(scene.id)}/picture?v=${scene.picture}`, alt: "", loading: "lazy", decoding: "async" });
    }
    return artworkImage(scene.artworkId, className);
  }

  /// The menu entries that give a scene, Homeswift's or a hub's, a picture of the person's own or take it away.
  /// `tileNode` shows busy while the picture is shrunk and sent.
  function pictureMenu(scene, tileNode) {
    const path = `/api/scenes/${encodeURIComponent(scene.id)}/picture`;
    return [
      { label: scene.picture ? t("Change the picture…") : t("Choose a picture…"), icon: "camera", onSelect: () => HomeswiftCommon.choosePictureFile(async (file) => {
        tileNode?.classList.add("busy");
        try {
          await app.api(path, { method: "PUT", body: { data: await HomeswiftCommon.pictureDataURL(file) } });
          app.route();
        } catch (e) { HomeswiftCommon.showAlert(e.message); tileNode?.classList.remove("busy"); }
      }) },
      scene.picture ? { label: t("Remove the picture"), icon: "trash", onSelect: async () => {
        if (!(await HomeswiftAdmin.confirmAction({ title: t("Remove the picture of {name}? Its tile goes back to its colours.", { name: scene.name }), confirmLabel: t("Remove"), confirmIcon: "trash" }))) return;
        tileNode?.classList.add("busy");
        try { await app.api(path, { method: "DELETE" }); app.route(); } catch (e) { HomeswiftCommon.showAlert(e.message); tileNode?.classList.remove("busy"); }
      } } : null,
    ].filter(Boolean);
  }

  const artworkThemeNames = {
    "Essentials": t("Essentials"),
    "Get cozy": t("Get cozy"),
    "Movie night": t("Movie night"),
    "Reading": t("Reading"),
    "Wanderlust": t("Wanderlust"),
    "Vibrant": t("Vibrant"),
    "Party vibes": t("Party vibes"),
    "Daily": t("Daily"),
    "Dreamy": t("Dreamy"),
    "Cozy": t("Cozy"),
    "Peaceful": t("Peaceful"),
    "Serenity": t("Serenity"),
    "Lush": t("Lush"),
    "Pure": t("Pure"),
    "Refreshing": t("Refreshing"),
    "Luxurious": t("Luxurious"),
    "Romantic": t("Romantic"),
    "Sunrise": t("Sunrise"),
    "Futuristic": t("Futuristic"),
    "Race day": t("Race day"),
    "Spring breeze": t("Spring breeze"),
    "Summer glow": t("Summer glow"),
    "Harvest hues": t("Harvest hues"),
    "Winter whisper": t("Winter whisper"),
    "Winter holidays": t("Winter holidays"),
    "Christmas": t("Christmas"),
    "Halloween": t("Halloween"),
    "More themes": t("More themes"),
  };
  let artworkThemesRequest;
  const loadArtworkThemes = () => artworkThemesRequest ||= app.api("/scene-artwork-themes.json").catch((error) => { artworkThemesRequest = null; throw error; });

  // A scene can belong to several themes; each row keeps the catalogue's order.
  function themedArtwork(items, themes, makeButton) {
    const byId = new Map(items.map((item) => [item.artworkId || item.id, item]));
    const search = el("input", { type: "search", placeholder: t("Search images…"), "aria-label": t("Search images…") });
    const select = el("select", { "aria-label": t("Theme") }, el("option", { value: "", text: t("All themes") }),
      [...themes].sort((a, b) => (artworkThemeNames[a.name] || a.name).localeCompare(artworkThemeNames[b.name] || b.name, HomeswiftI18n.locale)).map((theme) => el("option", { value: theme.name, text: artworkThemeNames[theme.name] || theme.name })));
    const sort = el("select", { "aria-label": t("Sort images") },
      el("option", { value: "gallery", text: t("Gallery order") }), el("option", { value: "asc", text: t("Name: A–Z") }), el("option", { value: "desc", text: t("Name: Z–A") }));
    const empty = el("p", { class: "muted", text: t("No images match your search."), hidden: true });
    const groups = themes.map((theme) => {
      const buttons = theme.artworkIds.filter((id) => byId.has(id)).map((id) => {
        const item = byId.get(id), button = makeButton(item);
        return { item, button };
      });
      const node = el("section", { class: "artwork-theme" }, el("h3", { class: "service-name", text: artworkThemeNames[theme.name] || theme.name }),
        el("div", { class: "artwork-theme-row" }, buttons.map(({ button }) => button)));
      return { theme, node, buttons };
    });
    const filter = () => {
      const query = search.value.trim().toLocaleLowerCase();
      for (const group of groups) {
        const matchesTheme = (artworkThemeNames[group.theme.name] || group.theme.name).toLocaleLowerCase().includes(query);
        for (const { item, button } of group.buttons) button.hidden = !(matchesTheme || item.name.toLocaleLowerCase().includes(query));
        group.node.hidden = (select.value && group.theme.name !== select.value) || !group.buttons.some(({ button }) => !button.hidden);
      }
      empty.hidden = groups.some(({ node }) => !node.hidden);
    };
    sort.addEventListener("change", () => {
      for (const group of groups) {
        const ordered = [...group.buttons];
        if (sort.value !== "gallery") ordered.sort((a, b) => a.item.name.localeCompare(b.item.name, HomeswiftI18n.locale) * (sort.value === "desc" ? -1 : 1));
        group.node.querySelector(".artwork-theme-row").replaceChildren(...ordered.map(({ button }) => button));
      }
    });
    search.addEventListener("input", filter); select.addEventListener("change", filter);
    return el("div", { class: "artwork-themes" }, el("div", { class: "artwork-filters" }, search, select, sort), empty, groups.map(({ node }) => node));
  }

  /// The animation styles, by id, in the order the editor lists them.
  const effectStyleNames = {
    candle: t("Candle"), fire: t("Fire"), sparkle: t("Sparkle"), prism: t("Prism"), opal: t("Opal"), glisten: t("Glisten"),
    underwater: t("Underwater"), cosmos: t("Cosmos"), sunbeam: t("Sunbeam"), enchant: t("Enchant"), palette: t("Moving colours"),
    sunrise: t("Sunrise"), sunset: t("Sunset"), music: t("Follow the music"),
  };

  function sceneButton(scene) {
    const picture = sceneImage(scene, "quick-scene-image");
    const button = el("button", { type: "button", class: `scene-run${picture ? " pictured" : ""}`, title: t("Run {name}", { name: scene.name }) }, picture, el("span", { class: "quick-scene-label" }, HomeswiftCommon.icon("play"), el("span", { text: scene.name })));
    button.addEventListener("click", () => runScene(scene, button));
    return button;
  }

  /// A hub scene's colours, as a tile's background when it has no picture.
  function paintColours(button, scene) {
    const colours = (scene.colours || []).filter((colour) => /^#[0-9a-f]{3,8}$/i.test(colour));
    if (colours.length) button.style.background = colours.length > 1 ? `linear-gradient(135deg, ${colours.join(", ")})` : colours[0];
    return colours.length > 0;
  }
  /// Whether its hub lets Homeswift run a scene (an IKEA wake-up runs on its own and is only shown).
  const canRecall = (scene) => (scene.capabilities || []).includes("recall");
  const collator = new Intl.Collator(HomeswiftI18n.locale);

  /// The parts every scene tile shares: a button with its picture or colours, the play glyph, its name and a line under
  /// it, Scene active while it is; round actions over its top corner. `extra` adds to the button (marks, a count).
  function sceneTileShell({ scene, label, detail, compact = false, active = scene.active, className = "", extra = null, actions = [], onClick, attributes = {} }) {
    const picture = compact ? null : sceneImage(scene, "quick-scene-image");
    const button = el("button", { type: "button", ...attributes, class: `scene-run hub-scene${className ? ` ${className}` : ""}${compact ? " compact" : ""}${picture ? " pictured" : ""}${active ? " active" : ""}` },
      picture,
      el("span", { class: "quick-scene-label" }, HomeswiftCommon.icon("play"),
        el("span", {}, el("span", { text: label }), detail ? el("span", { class: "scene-source", text: detail }) : null)),
      active ? el("span", { class: "pill scene-active", text: t("Scene active") }) : extra);
    if (!picture && !compact && paintColours(button, scene)) button.classList.add("coloured");
    if (onClick) button.addEventListener("click", () => onClick(button));
    return { button, node: el("div", { class: `hub-scene-tile${compact ? " compact" : ""}` }, button, el("div", { class: "hub-scene-actions" }, actions)) };
  }
  /// Runs a scene from its tile, then redraws the page's tiles to say what is active and what can stop.
  const runFromTile = async (scene, button) => { if (await runScene(scene, button)) redrawScenes(); };
  /// Stop, while a scene can be: round, on its tile.
  const stopButton = (scene) => {
    if (!scene.stoppable) return null;
    const stop = el("button", { type: "button", actionIcon: "stop", "aria-label": t("Stop"), title: t("Stop"), onclick: () => stopScene(scene, stop) });
    return stop;
  };

  /// A scene a plugin's hub keeps (Hue, IKEA, Govee): its picture or its colours, its source, whether the hub says it
  /// is on now. Running it recalls it on the hub. `label` and `detail` replace its name and its source on the tile (a
  /// group's sheet names each copy by its room); `compact` draws it as a small button, for scenes run by name.
  function hubSceneButton(scene, options = {}) {
    const { label = scene.name, detail = scene.source.pluginName, compact = false } = options;
    const runnable = canRecall(scene);
    // A Homeswift scene that recalls it, which an automation can then apply.
    let automating = false;
    const automate = async () => {
      if (automating) return;
      automating = true;
      try {
        const saved = await app.api("/api/scenes", { method: "POST", body: { name: scene.name.slice(0, 64), artworkId: scene.artworkId || null, actions: [{ recall: scene.id }] } });
        // An automation that applies it, for its triggers to be chosen.
        HomeswiftAutomations.draft({ name: scene.name.slice(0, 64), steps: [{ type: "scene", scene: saved.id }] });
      } catch (e) { HomeswiftCommon.showAlert(e.message); automating = false; }
    };
    let button;
    // Everything in its menu changes scenes or pictures: an administrator's.
    const menu = !app.isAdmin() ? null : menuButton(t("Actions for {name}", { name: scene.name }), () => [
      runnable ? { label: t("Automate"), icon: "workflow", onSelect: automate } : null,
      ...hubSceneMenu(scene), ...pictureMenu(scene, button),
    ].filter(Boolean));
    const shell = sceneTileShell({ scene, label, detail, compact, actions: [stopButton(scene), menu],
      attributes: { disabled: !runnable, title: runnable ? t("Run {name}", { name: scene.name }) : scene.name },
      onClick: (pressed) => runFromTile(scene, pressed) });
    button = shell.button;
    return sceneTile(shell.node, [scene], ([fresh]) => hubSceneButton(fresh, options));
  }

  /// What a hub's scene lets Homeswift change on its hub (its `capabilities`): its name, its lights' values as they are
  /// now, or the scene itself, which goes from the hub's own app too.
  function hubSceneMenu(scene) {
    const can = new Set(scene.capabilities || []);
    const path = `/api/scenes/${encodeURIComponent(scene.id)}`;
    const change = async (body) => {
      try { await app.api(`${path}/hub`, { method: "PUT", body }); app.route(); } catch (e) { HomeswiftCommon.showAlert(e.message); }
    };
    return [
      can.has("rename") ? { label: t("Rename…"), icon: "edit", onSelect: async () => {
        const name = (await HomeswiftCommon.promptDialog(t("A new name for {name} on {hub}.", { name: scene.name, hub: scene.source.name }), scene.name))?.trim();
        if (name && name !== scene.name) await change({ name });
      } } : null,
      can.has("update") && scene.accessoryIds?.length ? { label: t("Keep the lights as they are"), icon: "check", onSelect: async () => {
        if (await HomeswiftAdmin.confirmAction({ title: t("Update {name}?", { name: scene.name }), text: t("{name} on {hub} will set its lights as they are now.", { name: scene.name, hub: scene.source.name }), confirmLabel: t("Update"), danger: false })) await change({ fromCurrent: true });
      } } : null,
      can.has("delete") ? { label: t("Delete from {hub}", { hub: scene.source.name }), icon: "trash", danger: true, onSelect: async () => {
        if (!(await HomeswiftAdmin.confirmAction({ title: t("Delete the scene {name}?", { name: scene.name }), text: t("This removes it from {hub} and its own app too. This cannot be undone.", { hub: scene.source.name }), confirmLabel: t("Delete"), confirmIcon: "trash" }))) return;
        try { await app.api(path, { method: "DELETE" }); app.route(); } catch (e) { HomeswiftCommon.showAlert(e.message); }
      } } : null,
    ].filter(Boolean);
  }

  /// Where a hub's scene is: the room Homeswift gives it, else its room or zone on the hub (a Hue zone), else nowhere.
  const scenePlace = (scene) => scene.room || scene.hubRoom || "";
  /// A scene's name as the search and the grouping compare it: no accents, no case, single spaces.
  const foldedNames = new WeakMap();
  const foldedName = (scene) => {
    if (!foldedNames.has(scene)) foldedNames.set(scene, HomeswiftCommon.fold(scene.name.trim().replace(/\s+/g, " ")));
    return foldedNames.get(scene);
  };
  /// Scenes that are the same scene in several places: a hub makes Relax or Concentrate in each of its rooms, and a
  /// home keeps copies under one name. Same source and same name, whatever the accents, the case and the spaces.
  function sceneGroups(scenes) {
    const groups = new Map();
    for (const scene of scenes) {
      const key = `${scene.source.platform}\u0000${scene.source.name}\u0000${foldedName(scene)}`;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(scene);
    }
    return [...groups.values()];
  }
  /// A group whose copies are each in a room of their own (Hue's Relax): one per room, run there or in all of them.
  const inEveryRoom = (group) => group.every(scenePlace) && new Set(group.map(scenePlace)).size === group.length;

  /// Runs every copy of a group its hub lets run, together, then redraws the tiles once.
  async function runSceneGroup(group) {
    await Promise.all(group.filter(canRecall).map((scene) => runScene(scene)));
    await redrawScenes();
  }
  /// Stops every copy of a group that can stop, together, then redraws the tiles once.
  async function stopSceneGroup(group) {
    await Promise.all(group.filter((scene) => scene.stoppable).map((scene) => stopScene(scene, null, { redraw: false })));
    await redrawScenes();
  }

  /// A group's copies in a sheet (from the right, from the bottom on a phone), each with its own tile (run, stop, its ⋯
  /// menu) named by its room, and Run in every room. Its tiles follow runs and stops (`redrawScenes`); a rename or a
  /// delete draws the page again (`app.route`), and the sheet, whose tiles are the old page's, goes with it.
  let sheetSequence = 0;
  function sceneGroupSheet(group) {
    const first = group[0], rooms = inEveryRoom(group), id = `scene-group-${++sheetSequence}`;
    const tiles = group.map((scene, index) => hubSceneButton(scene, rooms
      ? { label: scenePlace(scene), detail: "" }
      : { label: scenePlace(scene) || scene.name, detail: t("{n} of {count}", { n: index + 1, count: group.length }) }));
    const all = rooms && group.filter(canRecall).length > 1
      ? el("button", { type: "button", class: "primary", actionIcon: "play", text: t("Run in every room"), onclick: () => HomeswiftCommon.busyButton(all, () => runSceneGroup(group)) }) : null;
    let close = () => {};
    const page = new MutationObserver(() => close());
    page.observe(document.getElementById("view"), { childList: true });
    app.openSheet((done) => {
      close = done;
      return el("div", { class: "account-form scene-group-sheet" },
        el("h2", { id, text: first.name }),
        el("p", { class: "muted", text: rooms ? tn("{source} has it in {n} room. Run it there, or change it from its ⋯ menu.", "{source} has it in {n} rooms. Run it in one, in every room, or change one from its ⋯ menu.", group.length, { source: first.source.name })
          : tn("{source} has {n} scene with this name.", "{source} has {n} scenes with this name: copies, perhaps. Run one, or rename or delete one from its ⋯ menu.", group.length, { source: first.source.name }) }),
        el("div", { class: "quick-scenes" }, tiles),
        el("div", { class: "actions" }, el("button", { type: "button", actionIcon: "close", text: t("Close"), onclick: () => done() }), all));
    }, id, { onClose: () => page.disconnect() });
  }

  /// The tile of a scene a hub has in several places, or under one name several times: the picture of one of them
  /// (an active one first), where it is, and Scene active while one is. A tap opens its copies (`sceneGroupSheet`);
  /// its ⋯ runs or stops them all.
  function sceneGroupTile(group, { compact = false } = {}) {
    const shown = group.find((scene) => scene.active) || group.find((scene) => scene.picture || scene.artworkId) || group[0];
    const rooms = inEveryRoom(group);
    const places = group.map(scenePlace);
    const copies = t("×{n}", { n: group.length });
    const where = rooms ? (places.length > 2 ? tn("{n} room", "{n} rooms", places.length) : places.join(", ")) : null;
    const menu = menuButton(t("Actions for {name}", { name: shown.name }), () => [
      rooms && group.some(canRecall) ? { label: t("Run in every room"), icon: "play", onSelect: () => runSceneGroup(group) } : null,
      group.some((scene) => scene.stoppable) ? { label: t("Stop"), icon: "stop", onSelect: () => stopSceneGroup(group) } : null,
      { label: rooms ? t("Rooms…") : t("Copies…"), icon: rooms ? "room" : "copy", onSelect: () => sceneGroupSheet(group) },
    ].filter(Boolean));
    const { node } = sceneTileShell({ scene: shown, label: shown.name, compact, className: "scene-group",
      detail: where || (compact ? null : copies), active: group.some((scene) => scene.active),
      extra: !where && compact ? el("span", { class: "scene-copies", text: copies }) : null,
      actions: [menu], attributes: { "aria-haspopup": "dialog", title: shown.name }, onClick: () => sceneGroupSheet(group) });
    return sceneTile(node, group, (fresh) => sceneGroupTile(fresh, { compact }));
  }

  /// The scenes of the plugins' hubs, each once: a hub's scene in several rooms is one tile (Hue makes Relax in each),
  /// the most widespread first and a dozen of them until Show all; scenes in no room (Apple Home's, through Wingman)
  /// are small buttons by name under Around the house. A source filter when there are several hubs. `filter({ place,
  /// query })` narrows both, a place showing its own copies, each with its menu; it answers how many show. The groups
  /// are made once and each tile drawn once: a filter only puts the tiles it keeps back in order.
  function hubScenesSection(scenes) {
    if (!scenes.length) return { node: null, filter: () => 0, places: [] };
    const roomed = scenes.filter(scenePlace), loose = scenes.filter((scene) => !scenePlace(scene));
    const places = [...new Set(roomed.map(scenePlace))].sort(collator.compare);
    const byName = (a, b) => collator.compare(a[0].name, b[0].name);
    const moodGroups = sceneGroups(roomed).sort((a, b) => b.length - a.length || byName(a, b));
    const looseGroups = sceneGroups(loose).sort(byName);
    // The source shows on a small button only when the scenes in no room come from more than one hub.
    const looseSources = new Set(loose.map((scene) => `${scene.source.platform}:${scene.source.name}`)).size;
    const sourceKey = (scene) => `${scene.source.platform}:${scene.source.name}`;
    const sources = [...new Map(scenes.map((scene) => [sourceKey(scene), scene.source.name])).entries()];
    const source = sources.length > 1 ? el("select", { "aria-label": t("Source") }, el("option", { value: "", text: t("All sources") }),
      sources.map(([key, name]) => el("option", { value: key, text: name }))) : null;
    const count = el("span", { class: "pill", text: String(scenes.length) });
    const moods = el("div", { class: "quick-scenes scene-moods" });
    const moreLabel = el("span", { class: "label" });
    const more = el("button", { type: "button", class: "scene-more", actionIcon: "down" }, moreLabel);
    const around = el("div", { class: "chips" });
    const aroundSection = el("section", { class: "scene-around" }, el("h3", { class: "service-name", text: t("Around the house") }), around);
    // Each tile drawn once, by what it shows: a group's copies, small or not, and whether a room is chosen.
    const tiles = new Map();
    const tileFor = (members, compact, place) => {
      const key = `${compact ? "c" : "t"}${place ? "p" : ""}:${members.map((scene) => scene.id).join(",")}`;
      if (!tiles.has(key)) {
        tiles.set(key, members.length > 1 ? sceneGroupTile(members, { compact })
          : hubSceneButton(members[0], compact ? { compact, detail: looseSources > 1 ? members[0].source.name : "" }
            : { detail: place ? members[0].source.pluginName : scenePlace(members[0]) || members[0].source.pluginName }));
      }
      return tiles.get(key);
    };
    let state = { place: "", query: "" }, showAll = false;
    const filter = (next = state) => {
      state = next;
      const keep = (scene) => (!state.query || foldedName(scene).includes(state.query)) && (!source?.value || sourceKey(scene) === source.value);
      const shownMoods = moodGroups.map((group) => group.filter((scene) => keep(scene) && (!state.place || scenePlace(scene) === state.place))).filter((group) => group.length);
      const limited = !showAll && !state.place && !state.query && shownMoods.length > 12;
      moods.replaceChildren(...(limited ? shownMoods.slice(0, 12) : shownMoods).map((group) => tileFor(group, false, state.place)));
      more.hidden = !limited;
      moreLabel.textContent = t("Show all {count}", { count: shownMoods.length });
      const shownLoose = state.place ? [] : looseGroups.map((group) => group.filter(keep)).filter((group) => group.length);
      around.replaceChildren(...shownLoose.map((group) => tileFor(group, true, "")));
      aroundSection.hidden = !shownLoose.length;
      const shown = [...shownMoods, ...shownLoose].reduce((sum, group) => sum + group.length, 0);
      count.textContent = String(shown);
      node.hidden = !shown;
      return shown;
    };
    more.addEventListener("click", () => { showAll = true; filter(); });
    const node = el("section", { class: "hub-scenes" },
      el("div", { class: "section-head hub-scenes-head" }, el("h2", { text: t("Scenes from your hubs") }), count, source),
      el("p", { class: "muted", text: t("Kept by the hubs of your plugins, such as a Hue Bridge, an IKEA hub or Govee lights. A scene a hub has in several rooms shows once: tap it to choose the room, or to rename, update or delete one from its ⋯ menu.") }),
      moods, more, aroundSection);
    filter();
    return { node, filter, places, source };
  }

  /// Runs a scene; one that changes a lock, a door or an alarm asks first, as the cards' own controls do.
  /// Puts back what a scene's last run changed (a saved scene's locks, doors and alarms once the person agrees), then
  /// redraws its tiles unless `redraw` is false (a group's Stop redraws once, after all of them).
  async function stopScene(scene, button, { redraw = true } = {}) {
    const confirmSecurity = Boolean(scene.security || scene.stopSecurity);
    if (confirmSecurity && !await HomeswiftCommon.confirmDialog(t("Restore the previous state of this scene’s locks, doors or alarms?"))) return;
    if (button) button.disabled = true;
    try {
      const result = await app.api(`/api/scenes/${encodeURIComponent(scene.id)}/stop`, { method: "POST", body: { confirmSecurity } });
      if (!result.ok) HomeswiftCommon.showAlert(result.failed.map((f) => HomeswiftI18n.message(f.error)).join("\n"));
      if (redraw) await redrawScenes();
    } catch (e) { HomeswiftCommon.showAlert(e.message); if (button) button.disabled = false; }
  }

  /// A scene tile (one scene's, or a group's, which shows several) and how to draw it again from fresh scenes, for
  /// `redrawScenes`. Wherever it is, the page or a sheet over it.
  const sceneTiles = new WeakMap();
  function sceneTile(node, scenes, draw) {
    node.dataset.scenes = scenes.map((scene) => scene.id).join(" ");
    sceneTiles.set(node, draw);
    return node;
  }
  /// After a run or a stop, the scenes' tiles on the page say what is active and what can stop: they are drawn again
  /// in place, rather than the whole view, which a phone shows as the page loading again and back at its top. The
  /// tiles stay the same nodes, so a filter that keeps them keeps working.
  async function redrawScenes() {
    const data = await app.api("/api/scenes").catch(() => null);
    if (!data) return;
    const scenes = new Map([...data.scenes, ...(data.pluginScenes || [])].map((scene) => [scene.id, scene]));
    for (const node of document.querySelectorAll("[data-scenes]")) {
      const draw = sceneTiles.get(node);
      const fresh = node.dataset.scenes.split(" ").map((id) => scenes.get(id)).filter(Boolean);
      if (!draw || !fresh.length) continue;
      const drawn = draw(fresh);
      node.className = drawn.className;
      node.replaceChildren(...drawn.childNodes);
    }
  }

  async function runScene(scene, button) {
    let confirmSecurity = false;
    if (scene.security) {
      const which = scene.actions.filter((a) => a.security).map((a) => `${a.name || a.id}: ${characteristicName(a.characteristic)}`).join(", ");
      if (!await HomeswiftCommon.confirmDialog(t("{scene} changes a lock, a door or an alarm ({which}). Run it?", { scene: scene.name, which }))) return;
      confirmSecurity = true;
    }
    button?.classList.add("busy");
    if (button) button.disabled = true;
    try {
      const result = await app.api(`/api/scenes/${encodeURIComponent(scene.id)}/run`, { method: "POST", body: { confirmSecurity } });
      if (!result.ok && result.results) {
        const failures = result.results.filter((r) => !r.ok).map((r) => `${r.name || r.id} ${characteristicName(r.characteristic)}: ${HomeswiftI18n.message(r.error || r.skipped)}`);
        HomeswiftCommon.showAlert(t("{scene} ran, but not everything worked:\n{failures}", { scene: scene.name, failures: failures.join("\n") }));
      }
      return result;
    } catch (e) { HomeswiftCommon.showAlert(e.message); } finally {
      button?.classList.remove("busy");
      if (button) button.disabled = false;
    }
  }

  // ---- Templates -------------------------------------------------------------------------------------

  /// The collection's names and descriptions, by id: translated here, the server's being English for MCP clients.
  const templateTexts = {
    "candlelight": [t("Candlelight"), t("Very warm, dim light for dinner.")],
    "relax": [t("Relax"), t("Soft warm white for the evening.")],
    "golden-hour": [t("Golden hour"), t("Amber and soft orange, a little different on each light.")],
    "cinema": [t("Cinema"), t("Almost dark, with a touch of blue behind the screen.")],
    "romantic": [t("Romantic"), t("Deep pink and soft red, dimmed.")],
    "focus": [t("Focus"), t("Bright, cool white for work.")],
    "night-light": [t("Night light"), t("A faint amber glow to find your way.")],
    "candle-flicker": [t("Candle flicker"), t("Warm amber, each light flickering on its own.")],
    "fireplace": [t("Fireplace"), t("Reds, oranges and amber dancing unevenly.")],
    "ocean": [t("Ocean"), t("Blues and teals rolling from light to light like waves.")],
    "northern-lights": [t("Northern lights"), t("Green, teal and violet drifting slowly.")],
    "breathing": [t("Breathing"), t("Soft light rising and falling in a six-second rhythm, to calm down.")],
    "sunset": [t("Sunset"), t("Ten minutes from golden yellow through orange and pink to a dim red.")],
    "sunrise": [t("Sunrise"), t("Fifteen minutes from a dim red glow to bright warm white, to wake up.")],
    "disco": [t("Disco"), t("Every light jumps to a vivid colour on each beat.")],
    "police": [t("Police siren"), t("Red and blue swapping from light to light.")],
    "rainbow-wave": [t("Rainbow wave"), t("The colour wheel passing from light to light.")],
    "lightning": [t("Lightning storm"), t("Dim stormy blue, with sudden white flashes.")],
    "halloween": [t("Halloween"), t("Purple and orange with an eerie flicker.")],
    "christmas": [t("Christmas"), t("Red and green taking turns, with a warm white twinkle now and then.")],
    "alert": [t("Alert flash"), t("Two red pulses, then the lights go back to how they were.")],
    "bedtime": [t("Bedtime"), t("A slow fade to a dim red over fifteen minutes.")],
  };
  const templateCategories = [["gallery", t("Scene gallery")], ["calm", t("Calm")], ["animated", t("Slow animations")], ["party", t("Party")], ["signal", t("Signals")]];
  const templateName = (id, name) => templateTexts[id]?.[0] ?? name;
  const templateRoomKey = "homeswift.templates.room";
  const ideasOpenKey = "homeswift.scenes.ideas";
  const scenePlaceKey = "homeswift.scenes.place";

  /// The rooms with a light in them, for the templates.
  function lightRooms(accessories) {
    const rooms = accessories.filter((a) => !a.hidden && a.room && a.services.some((s) => s.type === "Lightbulb")).map((a) => a.room);
    return [...new Set(rooms)].sort((a, b) => a.localeCompare(b, HomeswiftI18n.locale));
  }

  /// Ideas, folded on the Scenes page until opened (open while a try still plays, and as the person left it):
  /// templates for a room's lights, the rooms as chips, what was tried there and can still be stopped or undone, a box
  /// where the Assistant writes a scene from a description, and the collection by kind. A tap tries one at once without
  /// saving it (the pill lights up while it plays); Save keeps it as a scene. On a phone each kind is a row that swipes
  /// sideways, so the whole card fits on a screen.
  function templatesSection(accessories) {
    const section = el("details", { class: "card templates", id: "ideas" });
    try { section.open = localStorage.getItem(ideasOpenKey) === "1"; } catch {}
    section.addEventListener("toggle", () => { try { localStorage.setItem(ideasOpenKey, section.open ? "1" : "0"); } catch {} });
    const head = el("summary", {}, el("span", { class: "templates-title" }, sparkle(), el("strong", { text: t("Ideas") }), el("span", { class: "templates-chevron" }, HomeswiftCommon.icon("down"))),
      el("span", { class: "muted", text: t("Templates to try on a room's lights, and scenes the Assistant writes from a description. Nothing is kept until you save it.") }));
    const rooms = lightRooms(accessories);
    if (!rooms.length) {
      section.append(head, el("p", { class: "muted", text: t("Put your lights in rooms (a card's menu on the Accessories page) to try templates on them.") }));
      return section;
    }
    let room = rooms[0];
    try { const remembered = localStorage.getItem(templateRoomKey); if (rooms.includes(remembered)) room = remembered; } catch {}
    const roomChips = roomChipGroup(rooms, room, (name) => {
      room = name;
      try { localStorage.setItem(templateRoomKey, name); } catch {}
      drawTries();
      markPlaying();
    }).node;
    const line = statusLine();
    const running = el("div", { class: "template-running" });
    const collection = el("div", { class: "template-collection" });
    const describe = el("input", { type: "text", maxLength: 500, enterKeyHint: "go", placeholder: t("Describe a scene…"), title: t("Describe one: a jazz bar, a rainy afternoon…"), "aria-label": t("Describe a scene") });
    const create = el("button", { type: "submit", class: "primary template-create" }, sparkle(), el("span", { text: t("Create") }));
    const designer = el("form", { class: "template-describe hidden" }, describe, create);
    const templatesHead = el("div", { class: "service-name", text: t("From a template") });
    section.append(head, el("div", { class: "template-card" }, roomChips, running, line, designer, templatesHead, collection));

    let data = { templates: [], tries: [] };
    const buttons = [];
    const name = (run) => run.template ? templateName(run.template, run.name) : run.name;

    /// The pills of the templates playing in the chosen room light up.
    function markPlaying() {
      const playing = new Set(data.tries.filter((run) => run.room === room && run.template).map((run) => run.template));
      for (const [id, button] of buttons) {
        button.classList.toggle("playing", playing.has(id));
        button.setAttribute("aria-pressed", String(playing.has(id)));
        let badge = button.querySelector(".template-stop-badge");
        if (playing.has(id) && !badge) { badge = el("span", { class: "template-stop-badge", "aria-hidden": "true" }); button.append(badge); }
        if (!playing.has(id)) badge?.remove();
        const label = button.querySelector(".name")?.textContent || templateName(id, id);
        button.setAttribute("aria-label", playing.has(id) ? `${t("Stop")} ${label}` : label);
      }
    }

    async function refresh() {
      data = await app.api("/api/scenes/templates");
      drawTries();
      markPlaying();
    }

    async function stopTry(run) {
      await app.api(`/api/scenes/${encodeURIComponent(run.run)}/stop`, { method: "POST", body: {} });
      say(line, run.playing ? t("{scene} stopped: the lights are back as they were.", { scene: name(run) }) : t("{scene} undone: the lights are back as they were.", { scene: name(run) }));
    }

    function drawTries() {
      running.replaceChildren(...data.tries.map((run) => {
        // One that plays is stopped; one that set the lights once is undone. Either way the lights go back.
        const stop = el("button", { type: "button", class: "template-stop", actionIcon: "stop", text: run.playing ? t("Stop") : t("Undo") });
        stop.addEventListener("click", async () => {
          stop.classList.add("busy");
          stop.disabled = true;
          try { await stopTry(run); await refresh(); } catch (e) { say(line, e.message, "error"); stop.disabled = false; stop.classList.remove("busy"); }
        });
        const save = el("button", { type: "button", class: "link", actionIcon: "check", text: t("Save as a scene"), onclick: () => saveAsScene(run) });
        // The room shows only when it is not the one chosen above.
        const time = timeFormat.format(new Date(run.startedAt));
        const where = run.room && run.room !== room ? t("{room}, {time}", { room: run.room, time }) : time;
        return el("div", { class: "template-run" }, swatch(run.template, run.plan?.artworkId),
          el("div", { class: "template-run-text" }, el("strong", { text: name(run) }), el("span", { class: "muted", text: where })),
          save, stop);
      }));
    }

    function swatch(id, artworkId) {
      return artworkImage(artworkId || data.templates.find((template) => template.id === id)?.artworkId || "tyrell", "template-swatch");
    }

    async function start(body, label, button) {
      if (button?.classList.contains("busy")) return;
      button?.classList.add("busy");
      say(line, body.description ? t("The Assistant is writing a scene…") : t("Trying {template}…", { template: label }));
      try {
        const result = await app.api("/api/scenes/try", { method: "POST", body: { ...body, room } });
        if (result.ok) say(line, "");
        else {
          const failures = (result.results || []).filter((r) => !r.ok).map((r) => `${r.name || r.id || r.recall}: ${HomeswiftI18n.message(r.error || r.skipped)}`).join("; ");
          say(line, t("{scene} is set, but not on every light: {failures}", { scene: body.template ? label : result.name, failures }), "error");
        }
        if (body.description) describe.value = "";
        await refresh();
      } catch (e) { say(line, e.message, "error"); } finally { button?.classList.remove("busy"); }
    }

    async function saveAsScene(run) {
      try {
        const scene = await app.api("/api/scenes", { method: "POST", body: { ...run.plan, name: t("{scene} in {room}", { scene: name(run), room: run.room || room }).slice(0, 64) } });
        say(line, t("Saved as the scene {name}.", { name: scene.name }));
        setTimeout(() => { if (section.isConnected) app.route(); }, 1200);
      } catch (e) { say(line, e.message, "error"); }
    }

    designer.addEventListener("submit", (event) => {
      event.preventDefault();
      const text = describe.value.trim();
      if (text) start({ description: text }, text, create);
    });

    // The collection is drawn the first time Ideas opens: folded, the page needs only what was tried, to open it while
    // one still plays.
    let drawn = false;
    let loaded = null;
    const drawCollection = async () => {
      if (drawn || !section.open) return;
      drawn = true;
      await loaded;
      const themes = await loadArtworkThemes();
      collection.replaceChildren(...templateCategories.map(([category, label]) => {
        const templates = data.templates.filter((template) => template.category === category);
        if (!templates.length) return null;
        const makeButton = (template) => {
          const label = templateName(template.id, template.name);
          const button = el("button", { type: "button", class: "template-button scene pictured artwork-choice", title: category === "gallery" ? label : templateTexts[template.id]?.[1] ?? template.description ?? "", "aria-pressed": "false" },
            swatch(template.id), el("span", { class: "name", text: label }));
          button.addEventListener("click", async () => {
            if (button.classList.contains("busy")) return;
            const active = data.tries.filter((run) => run.room === room && run.template === template.id);
            if (!active.length) return start({ template: template.id }, label, button);
            button.classList.add("busy");
            try {
              for (const run of active) await stopTry(run);
              await refresh();
            } catch (e) { say(line, e.message, "error"); }
            finally { button.classList.remove("busy"); }
          });
          buttons.push([template.id, button]);
          return button;
        };
        return el("div", { class: "template-group" }, el("div", { class: "service-name", text: label }),
          category === "gallery" ? themedArtwork(templates, themes, makeButton) : el("div", { class: "template-buttons" }, templates.map(makeButton)));
      }).filter(Boolean));
      markPlaying();
    };
    const opened = () => drawCollection().catch((e) => { drawn = false; say(line, e.message, "error"); });
    section.addEventListener("toggle", opened);
    loaded = refresh().then(() => designer.classList.toggle("hidden", !data.assistant));
    loaded.then(() => { if (data.tries.length) section.open = true; return opened(); }).catch((e) => say(line, e.message, "error"));
    return section;
  }

  // ---- Scenes ----------------------------------------------------------------------------------------

  const timeFormat = HomeswiftI18n.dateTimeFormat({ hour: "2-digit", minute: "2-digit" });
  const dateTimeFormat = HomeswiftI18n.dateTimeFormat({ dateStyle: "medium", timeStyle: "short" });

  function describeDays(days) {
    if (!days || !days.length || days.length === 7) return t("every day");
    const key = [...days].sort().join();
    if (key === "1,2,3,4,5") return t("on weekdays");
    if (key === "0,6") return t("at weekends");
    return t("on {days}", { days: days.map((d) => weekdays[d]).join(", ") });
  }
  /// "Sunset every day", "10 min before sunrise on weekdays".
  function describeSun(event, minutes, days) {
    const sunrise = event === "sunrise";
    const vars = { minutes: Math.abs(minutes || 0), days };
    if (!minutes) return sunrise ? t("Sunrise {days}", vars) : t("Sunset {days}", vars);
    if (minutes < 0) return sunrise ? t("{minutes} min before sunrise {days}", vars) : t("{minutes} min before sunset {days}", vars);
    return sunrise ? t("{minutes} min after sunrise {days}", vars) : t("{minutes} min after sunset {days}", vars);
  }
  /// "90 s", "5 min", "2 h".
  function describeSeconds(seconds = 0) {
    if (seconds >= 3600 && seconds % 3600 === 0) return t("{n} h", { n: seconds / 3600 });
    if (seconds >= 60 && seconds % 60 === 0) return t("{n} min", { n: seconds / 60 });
    return t("{n} s", { n: seconds });
  }
  /// A characteristic's name in the page's language, as the rows under All controls give it ("On" is Power here).
  const characteristicName = (type) => type === "On" ? t("Power")
    : window.HomeswiftWidgets?.characteristicName && type ? HomeswiftWidgets.characteristicName(type) : type;
  /// A trigger's value as the controls word it: Motion, Unsecured, On rather than true or 0.
  const worded = (trigger) => window.HomeswiftWidgets?.valueText ? HomeswiftWidgets.valueText({ type: trigger.characteristic, value: trigger.value }) : String(trigger.value);
  function describeTrigger(trigger, names) {
    const text = (() => {
      switch (trigger.type) {
        case "time": return t("At {time} {days}", { time: trigger.at, days: describeDays(trigger.days) });
        case "sun": return describeSun(trigger.event, trigger.offsetMinutes, describeDays(trigger.days));
        case "cron": return t("Cron {expression}", { expression: trigger.cron });
        case "characteristic": {
          const vars = { who: names.get(trigger.id) || trigger.id, characteristic: characteristicName(trigger.characteristic) };
          if (trigger.operator === "changes") return t("When {who} {characteristic} changes", vars);
          const comparison = operators.find(([o]) => o === trigger.operator)?.[1] ?? trigger.operator;
          return t("When {who} {characteristic} {comparison} {value}", { ...vars, comparison, value: worded(trigger) });
        }
        case "stays": {
          const comparison = operators.find(([o]) => o === trigger.operator)?.[1] ?? trigger.operator;
          return t("When {who} {characteristic} {comparison} {value} for {duration}", { who: names.get(trigger.id) || trigger.id, characteristic: characteristicName(trigger.characteristic),
            comparison, value: worded(trigger), duration: describeSeconds(trigger.forSeconds) });
        }
        case "threshold": {
          const vars = { who: names.get(trigger.id) || trigger.id, characteristic: characteristicName(trigger.characteristic), value: String(trigger.value) };
          return trigger.direction === "below" ? t("When {who} {characteristic} falls below {value}", vars) : t("When {who} {characteristic} rises above {value}", vars);
        }
        case "press": {
          const vars = { who: names.get(trigger.id) || trigger.id, button: trigger.service || t("its button") };
          return trigger.press === "double" ? t("When {button} of {who} is double-pressed", vars)
            : trigger.press === "long" ? t("When {button} of {who} is held", vars) : t("When {button} of {who} is pressed", vars);
        }
        case "presence": {
          if (trigger.id === anyoneHome) return trigger.arriving ? t("When the first Person comes home") : t("When the last Person leaves");
          const vars = { who: names.get(trigger.id) || trigger.id };
          return trigger.arriving ? t("When {who} comes home", vars) : t("When {who} leaves", vars);
        }
        default: return trigger.type;
      }
    })();
    return trigger.enabled === false ? t("{trigger} (off)", { trigger: text }) : text;
  }

  /// The Scenes and Automations pages, as tabs.
  const scenesTabs = (current) => HomeswiftCommon.subnav(t("Scenes and automations"), "", [["automations", t("Automations"), "workflow"], ["scenes", t("Scenes"), "play"], ["remotes", t("Remotes"), "remote"]], current);
  /// What a scene of Homeswift's is, in a line: its room, the Home app, its animation.
  function sceneSummary(scene) {
    return [scene.room, scene.homeKit ? t("In the Home app") : null,
      scene.animation ? t("Animated: {style}", { style: scene.animation.effect ? effectStyleNames[scene.animation.effect.style] || scene.animation.effect.style : t("Timed sequence") }) : null].filter(Boolean).join(" · ");
  }
  /// Its last run, or why its last automatic run was skipped when that came after.
  function sceneLastRun(scene) {
    if (scene.lastSkipped && (!scene.lastRun || scene.lastSkipped.at > scene.lastRun.at)) {
      return t("Skipped {date}: {reason}", { date: dateTimeFormat.format(new Date(scene.lastSkipped.at)), reason: HomeswiftI18n.message(scene.lastSkipped.reason) });
    }
    if (!scene.lastRun) return t("Never run");
    const vars = { date: dateTimeFormat.format(new Date(scene.lastRun.at)), trigger: scene.lastRun.trigger };
    return scene.lastRun.ok ? t("Last run {date} ({trigger})", vars) : t("Last run {date} ({trigger}), with errors", vars);
  }
  /// What a trigger shows as: a clock for a time or a cron, the sun, a sensor for an accessory's value.
  const triggerIcons = { time: "history", cron: "history", sun: "sun", characteristic: "sensor", stays: "sensor", threshold: "sensor", presence: "user", press: "switch" };
  /// Anyone Home's accessory (Presence): a `presence` trigger on it fires at the first arrival or the last departure.
  const anyoneHome = "Presence:anyone";

  /// A scene's details in a sheet, from its tile's menu: what it is, each action, its locks and doors, its last run,
  /// and Edit.
  function sceneDetailsSheet(scene, names) {
    const id = `scene-details-${++sheetSequence}`;
    const actions = scene.actions.map((action) => action.recall ? el("div", { class: "control" },
      el("span", { text: action.missing ? t("{name} (gone)", { name: action.name || action.recall }) : action.name || action.recall }),
      el("span", { class: "value", text: t("Hub scene") })) : el("div", { class: "control" },
      el("span", { text: action.missing ? t("{name} (gone)", { name: action.name || action.id }) : action.name || action.id }),
      el("span", { class: "value", text: `${characteristicName(action.characteristic)} → ${typeof action.value === "boolean" && !app.enumLabels[action.characteristic] ? (action.value ? t("On") : t("Off")) : app.labelFor(action.characteristic, action.value)}` })));
    app.openSheet((done) => el("div", { class: "account-form scene-details" },
      el("h2", { id, text: scene.name }),
      el("p", { class: "muted", text: sceneSummary(scene, names) }),
      el("div", { class: "controls" }, actions),
      scene.security ? el("p", { class: "muted note", text: t("It changes a lock, a door or an alarm: the page asks before running it, and automations leave those actions out.") }) : null,
      el("p", { class: "muted scene-last-run", text: sceneLastRun(scene) }),
      el("div", { class: "actions" }, el("button", { type: "button", actionIcon: "close", text: t("Close"), onclick: () => done() }),
        el("a", { class: "button primary", href: `/scenes/${encodeURIComponent(scene.id)}`, actionIcon: "edit", text: t("Edit"), onclick: () => done() }))), id);
  }

  /// A scene of Homeswift's as a picture tile, as the hubs' scenes are: a tap runs it; marks for the Home app, what
  /// starts it and a lock it changes; Stop while it can; its ⋯ for Details, Edit, its picture and Delete.
  function ownSceneTile(scene, names) {
    const marks = [
      scene.homeKit ? ["house", t("In the Home app")] : null,
      scene.security ? ["lock", t("It changes a lock, a door or an alarm")] : null,
    ].filter(Boolean);
    let button;
    const menu = menuButton(t("Actions for {name}", { name: scene.name }), () => [
      { label: t("Details…"), icon: "logs", onSelect: () => sceneDetailsSheet(scene, names) },
      { label: t("Edit"), icon: "edit", href: `/scenes/${encodeURIComponent(scene.id)}` },
      ...pictureMenu(scene, button),
      { label: t("Delete"), icon: "trash", danger: true, onSelect: async () => {
        if (!(await HomeswiftAdmin.confirmAction({ title: t("Delete the scene {name}?", { name: scene.name }), text: t("This removes the scene; automations that apply it skip it. This cannot be undone."), confirmLabel: t("Delete"), confirmIcon: "trash" }))) return;
        try { await app.api(`/api/scenes/${encodeURIComponent(scene.id)}`, { method: "DELETE" }); app.route(); } catch (e) { HomeswiftCommon.showAlert(e.message); }
      } },
    ]);
    const shell = sceneTileShell({ scene, label: scene.name, detail: sceneSummary(scene) || t("Run by hand"), className: "own-scene",
      extra: marks.length ? el("span", { class: "scene-marks" }, marks.map(([glyph, label]) => el("span", { title: label, "aria-label": label, role: "img" }, HomeswiftCommon.icon(glyph)))) : null,
      actions: [stopButton(scene), menu], attributes: { title: t("Run {name}", { name: scene.name }) }, onClick: (pressed) => runFromTile(scene, pressed) });
    button = shell.button;
    return sceneTile(shell.node, [scene], ([fresh]) => ownSceneTile(fresh, names));
  }

  /// Rooms as a row of chips, one pressed: the Scenes page's filter and the templates' room. `all` adds a first chip
  /// for every room (`""`).
  function roomChipGroup(names, current, onPick, { all = null, className = "template-rooms" } = {}) {
    const node = el("div", { class: className, role: "group", "aria-label": t("Room") });
    const press = (name) => { for (const chip of node.children) chip.setAttribute("aria-pressed", String(chip.dataset.room === name)); };
    node.append(...(all ? ["", ...names] : names).map((name) => el("button", { type: "button", class: "template-room", actionIcon: name ? "room" : "house",
      text: name || all, "data-room": name, "aria-pressed": String(name === current), onclick: () => { press(name); onPick(name); } })));
    return { node, press };
  }

  async function scenesView(main) {
    const [data, accessories] = await Promise.all([app.api("/api/scenes"), app.api("/api/accessories")]);
    const names = new Map(accessories.map((a) => [a.id, displayName(a)]));
    const own = data.scenes.map((scene) => ({ scene, node: ownSceneTile(scene, names) }));
    const sceneCount = el("span", { class: "pill", text: String(own.length) });
    const hubScenes = hubScenesSection(data.pluginScenes || []);
    // The places to narrow the page to: the rooms of Homeswift's scenes and the hubs' rooms and zones.
    const places = [...new Set([...data.scenes.map((scene) => scene.room).filter(Boolean), ...hubScenes.places])].sort(collator.compare);
    let place = "";
    try { const remembered = localStorage.getItem(scenePlaceKey); if (places.includes(remembered)) place = remembered; } catch {}
    const choosePlace = (name) => {
      place = name;
      try { localStorage.setItem(scenePlaceKey, name); } catch {}
      filter();
    };
    const placeChips = roomChipGroup(places, place, choosePlace, { all: t("All rooms"), className: "scene-places" });
    const search = el("input", { type: "search", class: "search", placeholder: t("Search scenes"), "aria-label": t("Search scenes") });
    // Back to every scene: the search, the room (remembered, so the page can open narrowed) and the source.
    const clear = HomeswiftCommon.clearFilters([[search, ""], ...(hubScenes.source ? [[hubScenes.source, ""]] : [])], {
      active: () => place !== "", reset: () => { placeChips.press(""); choosePlace(""); }, events: [[placeChips.node, "click"]] });
    const ownSection = el("section", { class: "own-scenes" },
      el("div", { class: "section-head" }, el("h2", { text: t("Your scenes") }), sceneCount),
      el("div", { class: "quick-scenes scene-moods" }, own.map(({ node }) => node)));
    const noMatches = el("p", { class: "card empty", hidden: true, text: t("No scene matches.") });
    function filter() {
      const query = HomeswiftCommon.fold(search.value.trim());
      for (const { scene, node } of own) node.hidden = !foldedName(scene).includes(query) || (place && scene.room !== place);
      const ownShown = own.filter(({ node }) => !node.hidden).length;
      sceneCount.textContent = String(ownShown);
      ownSection.hidden = !ownShown;
      const hubShown = hubScenes.filter({ place, query });
      noMatches.hidden = ownShown > 0 || hubShown > 0 || (!query && !place);
    }
    search.addEventListener("input", filter);
    const ideas = templatesSection(accessories);
    const reduceMotion = () => matchMedia("(prefers-reduced-motion: reduce)").matches;
    const ideasButton = el("button", { type: "button", actionIcon: "sparkle", text: t("Ideas"), onclick: () => {
      ideas.open = true;
      ideas.scrollIntoView({ behavior: reduceMotion() ? "auto" : "smooth", block: "start" });
    } });
    const newScene = () => el("a", { class: "button primary", href: "/scenes/new", actionIcon: "plus", text: t("New scene") });
    const anything = own.length || hubScenes.node;
    // With no scene of its own, a short line says what one is for: under the hubs' scenes, which are what there is to
    // run, or alone at the top.
    const empty = own.length ? null : el("div", { class: `card empty scenes-empty${hubScenes.node ? " compact" : ""}` }, el("span", { class: "empty-glyph" }, HomeswiftCommon.icon("play")),
      el("p", { class: "muted", text: hubScenes.node ? t("None of your own yet: a scene of yours sets several accessories at once, and an automation can apply it at sunset or when a door opens.") : t("No scene yet. A scene sets several accessories at once, such as every light of a room for the evening.") }),
      newScene());
    const sections = hubScenes.node ? [ownSection, noMatches, hubScenes.node, empty] : [empty, ownSection, noMatches];
    app.show(main,
      app.pageHead(t("Scenes"), t("Accessory values set together, by hand, from the Home app or by an automation. Homeswift keeps them; one you choose is also a switch in the Home app."),
        ideasButton, anything ? newScene() : null),
      scenesTabs("scenes"),
      anything ? el("div", { class: "scene-filters" }, search, clear, places.length > 1 ? placeChips.node : null) : null,
      ...sections, ideas);
    hubScenes.source?.addEventListener("change", filter);
    filter();
  }

  /// The characteristics of an accessory a scene can set: writable, not HomeKit's plumbing.
  function writable(accessory) {
    return accessory.services.filter((s) => !s.internal).flatMap((service) => service.characteristics
      .filter((c) => c.permissions.includes("pw") && c.permissions.includes("pr") && !c.internal && !["Identify", "Name", "Configured Name"].includes(c.type))
      .map((c) => ({ ...c, service: service.subtype || service.type, serviceName: service.name || service.type })));
  }
  function readable(accessory) {
    return accessory.services.filter((s) => !s.internal).flatMap((service) => service.characteristics
      .filter((c) => c.permissions.includes("pr") && !c.internal && !c.confidential && !["Identify", "Name", "Configured Name"].includes(c.type))
      .map((c) => ({ ...c, service: service.subtype || service.type, serviceName: service.name || service.type })));
  }

  /// An input for a characteristic's value: a menu for booleans and enumerations, a number within its range,
  /// else text. `.read()` gives the value to save.
  function valueInput(characteristic, value) {
    if (characteristic?.type === "Light color") return colorInput(value);
    if (["Brightness", "Color Temperature", "Hue", "Saturation", "Rotation Speed", "Target Position", "Volume", "Target Temperature", "Heating Threshold Temperature", "Cooling Threshold Temperature"].includes(characteristic?.type)) {
      const temperature = characteristic.type === "Color Temperature";
      const min = characteristic.minValue ?? (temperature ? 140 : 0);
      const max = characteristic.maxValue ?? (temperature ? 500 : characteristic.type === "Hue" ? 360 : 100);
      const slider = el("input", { type: "range", min, max, step: characteristic.minStep || 1,
        value: value ?? characteristic.value ?? min, "aria-label": characteristicName(characteristic.type) });
      const output = el("output", { class: "scene-slider-value" });
      const format = new Intl.NumberFormat(HomeswiftI18n.numberLocale, { maximumFractionDigits: 0 });
      const paint = () => {
        const raw = Number(slider.value);
        const unit = characteristic.unit === "celsius" ? " °C" : characteristic.type === "Hue" ? "°" : characteristic.unit === "percentage" || ["Brightness", "Saturation", "Rotation Speed", "Target Position", "Volume"].includes(characteristic.type) ? " %" : "";
        const text = temperature ? `${format.format(Math.round(1000000 / raw))} K` : characteristic.unit === "celsius" ? HomeswiftCommon.formatTemperature(raw) : `${raw}${unit}`;
        output.textContent = text;
        slider.setAttribute("aria-valuetext", text);
      };
      slider.addEventListener("input", paint); paint();
      const wrap = el("span", { class: `scene-value-slider${temperature ? " temperature" : " brightness"}` }, output, slider);
      wrap.read = () => Number(slider.value);
      return wrap;
    }
    const labels = app.enumLabels[characteristic?.type];
    // Eve's weather Condition: one of Open-Meteo's words, as the weather widget names them; a saved word it does not
    // know stays a choice.
    const words = characteristic?.type === "Condition" && characteristic.format === "string" ? window.HomeswiftWidgets?.weatherConditions?.() : null;
    let input;
    if (characteristic?.format === "bool") {
      input = el("input", { type: "checkbox", role: "switch", checked: Boolean(value ?? characteristic.value), "aria-label": characteristicName(characteristic.type) });
      input.read = () => input.checked;
    } else if (words) {
      const saved = value ?? characteristic.value;
      const choices = typeof saved === "string" && saved && !words.some(([word]) => word === saved) ? [...words, [saved, saved]] : words;
      input = el("select", {}, choices.map(([word, label]) => el("option", { value: word, text: label })));
      input.value = typeof saved === "string" && saved ? saved : choices[0][0];
      input.read = () => input.value;
    } else if (characteristic && (characteristic.validValues || labels)) {
      const values = characteristic.validValues || labels.map((_, index) => index);
      input = el("select", {}, values.map((v) => el("option", { value: v, text: app.labelFor(characteristic.type, v) })));
      input.value = String(value ?? values[0]);
      input.read = () => Number(input.value);
    } else if (characteristic && characteristic.format !== "string") {
      input = el("input", { type: "number", min: characteristic.minValue, max: characteristic.maxValue, step: characteristic.minStep || "any", value: value ?? characteristic.value ?? 0 });
      input.read = () => Number(input.value);
    } else {
      input = el("input", { type: "text", value: value ?? "", maxLength: 256 });
      // An accessory that is gone keeps its value as it was saved.
      input.read = () => !characteristic && input.value === String(value ?? "") && value !== undefined ? value : input.value;
    }
    input.setAttribute("aria-label", t("Value"));
    return input;
  }

  function colorControls(accessory) {
    const chars = writable(accessory);
    return [...chars, ...chars.filter((c) => c.type === "Hue" && chars.some((s) => s.type === "Saturation" && s.service === c.service))
      .map((c) => ({ ...c, type: "Light color", value: { hue: c.value, saturation: chars.find((s) => s.type === "Saturation" && s.service === c.service).value } }))];
  }

  function colorInput(value = {}) {
    const h = Number(value.hue || 0), sat = Number(value.saturation ?? 100) / 100;
    const channel = (n) => { const k = (n + h / 60) % 6; return Math.round(255 * (1 - sat * Math.max(0, Math.min(k, 4 - k, 1)))).toString(16).padStart(2, "0"); };
    const input = el("input", { type: "color", value: `#${channel(5)}${channel(3)}${channel(1)}`, "aria-label": t("Light color"), class: "scene-color-input" });
    let selected = { hue: h, saturation: sat * 100 };
    input.addEventListener("input", () => {
      const [r, g, b] = [1, 3, 5].map((i) => parseInt(input.value.slice(i, i + 2), 16) / 255);
      const max = Math.max(r, g, b), min = Math.min(r, g, b), d = max - min;
      const hue = d === 0 ? 0 : max === r ? ((g - b) / d + 6) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
      selected = { hue: Math.round(hue * 60), saturation: Math.round(max === 0 ? 0 : d / max * 100) };
    });
    input.read = () => selected;
    return input;
  }

  /// An accessory and one of its characteristics, with a value input after them when `withValue`.
  function characteristicPicker(accessories, pick, { id, service, characteristic, value, withValue = true, list = writable }) {
    const options = accessories.filter((a) => list(a).length);
    const accessory = el("select", { "aria-label": t("Accessory") }, options.map((a) => el("option", { value: a.id, text: displayName(a) })));
    const kind = el("select", { "aria-label": t("Characteristic") });
    const holder = el("span", { class: "value-slot" });
    let current = null;
    const fill = (keepType, keepValue) => {
      const found = options.find((a) => a.id === accessory.value);
      const chars = found ? list(found) : [];
      kind.replaceChildren(...chars.map((c, index) => el("option", { value: index, text: chars.filter((x) => x.type === c.type).length > 1 ? `${characteristicName(c.type)} (${c.serviceName})` : characteristicName(c.type) })));
      // An accessory that is gone keeps the characteristic it was saved with.
      if (!chars.length && (keepType ?? characteristic)) kind.append(el("option", { value: 0, text: characteristicName(keepType ?? characteristic) }));
      const index = Math.max(0, chars.findIndex((c) => c.type === keepType && (!service || c.service === service)));
      kind.value = String(index);
      current = chars[index] || null;
      if (withValue) { holder.replaceChildren(pick.value = valueInput(current, keepValue ?? current?.value)); }
    };
    if (id && options.some((a) => a.id === id)) accessory.value = id;
    else if (id) accessory.prepend(el("option", { value: id, text: t("{name} (gone)", { name: id }), selected: true }));
    fill(characteristic, value);
    accessory.addEventListener("change", () => fill());
    kind.addEventListener("change", () => {
      const found = options.find((a) => a.id === accessory.value);
      current = found ? list(found)[Number(kind.value)] : null;
      if (withValue) holder.replaceChildren(pick.value = valueInput(current, current?.value));
    });
    pick.read = () => {
      const found = options.find((a) => a.id === accessory.value);
      if (!found || !current) return { id: accessory.value, characteristic: characteristic || "", ...(service ? { service } : {}) };
      const several = list(found).filter((c) => c.type === current.type).length > 1;
      return { id: found.id, characteristic: current.type, ...(several ? { service: current.service } : {}) };
    };
    pick.current = () => current;
    return [accessory, kind, holder];
  }

  const rowShell = (...children) => el("div", { class: "editor-row" }, ...children);
  const removeButton = (row, list) => el("button", { class: "icon-button", type: "button", title: t("Remove"), "aria-label": t("Remove"), onclick: () => { list.delete(row); row.remove(); } }, HomeswiftCommon.icon("trash"));

  function daysPicker(days) {
    const chosen = new Set(days && days.length ? days : [0, 1, 2, 3, 4, 5, 6]);
    const node = el("span", { class: "days", role: "group", "aria-label": t("Days") }, weekdayOrder.map((day) => {
      const name = weekdayNames[day];
      const box = el("input", { type: "checkbox", checked: chosen.has(day), "aria-label": name });
      box.addEventListener("change", () => { if (box.checked) chosen.add(day); else chosen.delete(day); });
      return el("label", { class: "day", title: name }, box, el("span", { text: weekdays[day] }));
    }));
    node.read = () => chosen.size === 7 || chosen.size === 0 ? undefined : [...chosen].sort();
    return node;
  }

  function timeOfDay(value) {
    const sun = ["sunrise", "sunset"].includes(value);
    const kind = el("select", { "aria-label": t("When") }, el("option", { value: "time", text: t("At") }), el("option", { value: "sunrise", text: t("Sunrise") }), el("option", { value: "sunset", text: t("Sunset") }));
    kind.value = sun ? value : "time";
    const time = el("input", { type: "time", value: sun ? "00:00" : value || "18:00", "aria-label": t("Time"), title: HomeswiftCommon.homeTimeTitle() });
    time.classList.toggle("hidden", sun);
    kind.addEventListener("change", () => time.classList.toggle("hidden", kind.value !== "time"));
    const node = el("span", { class: "group-inline" }, kind, time);
    node.read = () => kind.value === "time" ? time.value : kind.value;
    return node;
  }

  /// A Trigger in an Automation's editor: its kind, its fields and On; `remove(row)` makes its delete button.
  /// `.read()` gives what to save.
  function triggerRow(accessories, trigger = { type: "time", at: "18:00" }, remove) {
    const type = el("select", { "aria-label": t("Trigger") },
      el("option", { value: "time", text: t("At a time") }), el("option", { value: "sun", text: t("Sunrise or sunset") }),
      el("option", { value: "characteristic", text: t("When an accessory changes") }), el("option", { value: "stays", text: t("When a value stays for a while") }),
      el("option", { value: "threshold", text: t("When a number crosses a threshold") }), el("option", { value: "cron", text: t("Cron") }));
    // Presence's Persons and Anyone Home, when the bridge has them (or the trigger names one already).
    const people = accessories.filter((one) => one.platform === "Presence")
      .sort((a, b) => (a.id === anyoneHome) - (b.id === anyoneHome) || displayName(a).localeCompare(displayName(b)));
    if (people.length || trigger.type === "presence") type.insertBefore(el("option", { value: "presence", text: t("When someone comes home or leaves") }), type.querySelector('[value="cron"]'));
    // Accessories with buttons (a remote's, a wall switch's): their Stateless Programmable Switches.
    const isButton = (service) => service.type === "StatelessProgrammableSwitch";
    const withButtons = accessories.filter((one) => one.services?.some(isButton)).sort((a, b) => displayName(a).localeCompare(displayName(b)));
    if (withButtons.length || trigger.type === "press") type.insertBefore(el("option", { value: "press", text: t("When a button is pressed") }), type.querySelector('[value="cron"]'));
    type.value = trigger.type;
    // Whether the trigger counts, in the row's head with its kind: apart from a Value switch in its fields.
    const enabled = el("input", { type: "checkbox", role: "switch", checked: trigger.enabled !== false });
    const body = el("span", { class: "group-inline grow" });
    const row = rowShell(el("div", { class: "trigger-head" }, type,
      el("label", { class: "toggle compact trigger-enabled" }, el("span", { class: "switch" }, enabled, el("span")), el("span", { text: t("Enabled") }))), body);
    const draw = (shown) => {
      if (shown.type === "time") {
        const at = el("input", { type: "time", value: shown.at || "18:00", "aria-label": t("Time"), title: HomeswiftCommon.homeTimeTitle() });
        const days = daysPicker(shown.days);
        body.replaceChildren(at, days);
        row.readBody = () => ({ at: at.value, days: days.read() });
      } else if (shown.type === "sun") {
        const event = el("select", { "aria-label": t("Event") }, el("option", { value: "sunrise", text: t("Sunrise") }), el("option", { value: "sunset", text: t("Sunset") }));
        event.value = shown.event || "sunset";
        const offset = el("input", { type: "number", min: -720, max: 720, step: 1, value: shown.offsetMinutes ?? 0, "aria-label": t("Minutes after (negative: before)"), title: t("Minutes after; negative for before") });
        const days = daysPicker(shown.days);
        body.replaceChildren(event, offset, el("span", { class: "muted", text: "min" }), days);
        row.readBody = () => ({ event: event.value, offsetMinutes: Number(offset.value) || 0, days: days.read() });
      } else if (shown.type === "characteristic") {
        const pick = {};
        const operator = el("select", { "aria-label": t("Condition") }, el("option", { value: "changes", text: t("changes") }), operators.map(([value, text]) => el("option", { value, text })));
        operator.value = shown.operator || "changes";
        const [accessory, kind, holder] = characteristicPicker(accessories, pick, { id: shown.id, characteristic: shown.characteristic, value: shown.value, list: readable });
        holder.classList.toggle("hidden", operator.value === "changes");
        operator.addEventListener("change", () => holder.classList.toggle("hidden", operator.value === "changes"));
        body.replaceChildren(field(t("Accessory"), accessory), field(t("Control"), kind), field(t("Comparison"), operator), field(t("Value"), holder));
        row.readBody = () => ({ ...pick.read(), operator: operator.value, ...(operator.value === "changes" ? {} : { value: pick.value.read() }) });
      } else if (shown.type === "stays") {
        const pick = {};
        const operator = el("select", { "aria-label": t("Comparison") }, operators.map(([value, text]) => el("option", { value, text })));
        operator.value = shown.operator || "eq";
        const [accessory, kind, holder] = characteristicPicker(accessories, pick, { id: shown.id, characteristic: shown.characteristic, value: shown.value, list: readable });
        // The duration in the unit it was saved in: 90 seconds stays 90 seconds.
        const seconds = shown.forSeconds ?? 300;
        const size = seconds % 3600 === 0 ? 3600 : seconds % 60 === 0 ? 60 : 1;
        const amount = el("input", { type: "number", min: 1, max: 86400, step: 1, value: seconds / size, "aria-label": t("For") });
        const unit = el("select", { "aria-label": t("Unit") }, el("option", { value: 1, text: t("seconds") }), el("option", { value: 60, text: t("minutes") }), el("option", { value: 3600, text: t("hours") }));
        unit.value = String(size);
        body.replaceChildren(field(t("Accessory"), accessory), field(t("Control"), kind), field(t("Comparison"), operator), field(t("Value"), holder), field(t("For"), amount), field(t("Unit"), unit));
        row.readBody = () => ({ ...pick.read(), operator: operator.value, value: pick.value.read(), forSeconds: Math.min(86400, Math.max(1, Math.round(Number(amount.value) || 1)) * Number(unit.value)) });
      } else if (shown.type === "threshold") {
        const pick = {};
        const numeric = (accessory) => readable(accessory).filter((c) => ["float", "int", "uint8", "uint16", "uint32", "uint64"].includes(c.format) && !c.validValues);
        const direction = el("select", { "aria-label": t("Direction") }, el("option", { value: "above", text: t("rises above") }), el("option", { value: "below", text: t("falls below") }));
        direction.value = shown.direction || "above";
        const [accessory, kind] = characteristicPicker(accessories, pick, { id: shown.id, characteristic: shown.characteristic, withValue: false, list: numeric });
        const value = el("input", { type: "number", step: "any", value: shown.value ?? 0, "aria-label": t("Value") });
        body.replaceChildren(field(t("Accessory"), accessory), field(t("Control"), kind), field(t("Direction"), direction), field(t("Value"), value));
        row.readBody = () => ({ ...pick.read(), direction: direction.value, value: Number(value.value) });
      } else if (shown.type === "press") {
        const accessory = el("select", { "aria-label": t("Accessory") }, withButtons.map((one) => el("option", { value: one.id, text: displayName(one) })));
        if (shown.id && !withButtons.some((one) => one.id === shown.id)) accessory.append(el("option", { value: shown.id, text: shown.id }));
        accessory.value = shown.id ?? withButtons[0]?.id ?? "";
        const button = el("select", { "aria-label": t("Button") });
        // Its buttons by the name their plugin gives them ("Channel 1 button"), which the trigger keeps.
        const buttons = () => {
          const services = (withButtons.find((one) => one.id === accessory.value)?.services ?? []).filter(isButton);
          button.replaceChildren(...services.map((s) => el("option", { value: s.name || s.subtype, text: s.name || s.subtype })));
          if (shown.service && ![...button.options].some((o) => o.value === shown.service)) button.append(el("option", { value: shown.service, text: shown.service }));
