      tile(glyph, device.status === "excluded" ? "grey" : device.status === "needsAuthorization" ? "orange" : "blue"),
      el("div", { class: "who" }, el("strong", { text: device.name }),
        el("span", { class: "help", text: detail, title: detail })),
