        });
        hit.addEventListener("pointermove", (event) => {
          if (!start) return;
          const moved = Math.abs(event.clientY - start.y);
          if (!armed) { if (moved > PRESS_SLOP) { clearTimeout(holdTimer); start = null; } return; }
          if (sliding === null && moved < 4) return;
